// Deliberately NOT AppBuilder.Definition.Tests: this file is compiled into three test projects, and a
// namespace naming one of them would read as a dependency on it from the other two.
namespace AppBuilder.TestCorpus;

/// <summary>
/// The one definition of "the corpus", shared by every suite that has to hold itself against real
/// definitions.
///
/// <para>It lives in this project because the gate is what the corpus was first assembled to protect,
/// but it is <b>source-linked</b> into the other test projects rather than reached through a project
/// reference — a test project referencing another test project drags its fixtures, its
/// <c>[MemberData]</c> and its whole dependency set along with it. The file is small and pure on
/// purpose; linking a file is cheap, and a second private copy of "which files are the corpus" is
/// exactly the drift that lets a new reference app be covered by one suite and silently skipped by
/// another.</para>
///
/// <para>Consumers today: <see cref="SchemaConformanceTests"/> (the gate + union safety net),
/// <c>AppBuilder.Cord.Tests</c> (round-trip and coverage), and <c>AppBuilder.Runtime.Tests</c>
/// (compile + pipeline). Adding a file under <c>exploration/reference/</c> enrols it in all of
/// them.</para>
/// </summary>
public static class Corpus
{
    /// <summary>Walks up from the test binary until the schema is underfoot. Anchored on the schema
    /// file rather than on <c>.git</c> or a directory name so it still works from a build output
    /// nested at an unknown depth.</summary>
    public static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "schema", "app-definition.schema.json")))
            dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("repo root not found from " + AppContext.BaseDirectory);
    }

    /// <summary>The maintained corpus: the hand-authored reference apps + the canonical CRM example.
    /// These are asserted FULLY gate-clean.</summary>
    public static TheoryData<string> MaintainedDefinitions()
    {
        var root = RepoRoot();
        var data = new TheoryData<string>();
        foreach (var p in Directory.GetFiles(Path.Combine(root, "exploration", "reference"), "*.appdef.json"))
            data.Add(p);
        data.Add(Path.Combine(root, "schema", "examples", "crm.appdef.json"));
        return data;
    }

    /// <summary>Every definition in the repo except the deliberately-invalid fixture — the widest
    /// net for the structural checks.</summary>
    public static TheoryData<string> AllDefinitions()
    {
        var root = RepoRoot();
        var data = new TheoryData<string>();
        foreach (var p in Directory.GetFiles(Path.Combine(root, "exploration", "reference"), "*.appdef.json"))
            data.Add(p);
        foreach (var p in Directory.GetFiles(Path.Combine(root, "schema", "examples"), "*.json", SearchOption.AllDirectories))
            if (!p.Replace('\\', '/').Contains("/invalid/")) data.Add(p);
        return data;
    }

    /// <summary>
    /// The maintained corpus plus Budget Planner — every app a semantic authoring layer must be able
    /// to represent.
    ///
    /// <para>Budget Planner is deliberately outside <see cref="MaintainedDefinitions"/>: it is not in
    /// <c>demo/load.py</c>'s suite and is an exploration artifact rather than a demo app. It is also
    /// the hardest document in the repo — 12 windowed rollups in both directions and at both scales,
    /// four <c>prev()</c> expressions, a series partition, a settings singleton — which makes it the
    /// one app no coverage claim may quietly exclude.</para>
    /// </summary>
    public static TheoryData<string> SemanticCorpus()
    {
        var data = new TheoryData<string>();
        foreach (var p in SemanticPaths()) data.Add(p);
        return data;
    }

    /// <summary>The same set as a plain list. <c>TheoryData</c> is awkward to aggregate over — it is
    /// built to be spread across test cases, not summed — and a coverage report needs the whole
    /// corpus at once. One list, two shapes, so the two can never name different files.</summary>
    public static IReadOnlyList<string> SemanticPaths()
    {
        var root = RepoRoot();
        var paths = new List<string>(Directory.GetFiles(Path.Combine(root, "exploration", "reference"), "*.appdef.json"))
        {
            Path.Combine(root, "schema", "examples", "crm.appdef.json"),
            Path.Combine(root, "exploration", "budget-planner.appdef.json"),
        };
        return paths;
    }

    /// <summary>The historical model-generated fixtures. NOT gate-clean and not asserted to be — they
    /// are v1.0-era shapes. They matter to anything claiming to read <i>any</i> definition, because
    /// <c>/editor</c> and refine can produce documents the gate rejects too.</summary>
    public static TheoryData<string> HistoricalDefinitions()
    {
        var dir = Path.Combine(RepoRoot(), "schema", "examples", "tests", "generated");
        var data = new TheoryData<string>();
        if (!Directory.Exists(dir)) return data;
        foreach (var p in Directory.GetFiles(dir, "*.json", SearchOption.AllDirectories))
            data.Add(p);
        return data;
    }
}

