5	/// <summary>Canaries for the composed schema (schema/app-definition.schema.json is GENERATED
6	/// from schema/src/ by compose.py). The composer copies def bodies verbatim, so these assert
7	/// the properties a composition bug would silently destroy: the block/effect if-then const
8	/// dispatch tables, the absence of <c>unevaluatedProperties</c> (it crashes this very test
9	/// host), and that JsonSchema.Net still parses the artifact the gate embeds.</summary>
10	public class SchemaCompositionTests
11	{
12	    private static readonly JsonObject Schema =
13	        JsonNode.Parse(Schemas.AppDefinitionSchemaJson)!.AsObject();
14	
15	    private static JsonObject Defs => Schema["$defs"]!.AsObject();
16	
17	    [Fact]
18	    public void Embedded_schema_parses_under_JsonSchemaNet()
19	    {
20	        // Schemas.AppDefinitionSchema is `static readonly` — touching it forces the parse.
21	        Assert.NotNull(Schemas.AppDefinitionSchema);
22	        Assert.Equal(81, Defs.Count);   // +effect_createForEach; +deepLink; +block_orgchart; +filterBar; +groupBy; +block_board; +block_gantt; +blockSearch; +block_filterbar; +block_history; +block_answers; +block_intake; +combine; +statMax; +effect_enrich; +block_externalEmbed; +block_relatedApps; +block_create; +timeAxis
23	    }
24	
25	    [Fact]
26	    public void Block_dispatch_covers_every_block_variant()
27	    {
28	        var variantKinds = Defs
29	            .Where(d => d.Key.StartsWith("block_"))
30	            .Select(d => d.Key["block_".Length..])
31	            .OrderBy(k => k)
32	            .ToArray();
33	        Assert.Equal(41, variantKinds.Length);   // +create (the page-level "New <record>" button)
34	
35	        var dispatched = Defs["block"]!["allOf"]!.AsArray()
36	            .Select(branch => branch?["if"]?["properties"]?["kind"]?["const"]?.GetValue<string>())
37	            .Where(k => k is not null)
38	            .OrderBy(k => k)
39	            .ToArray();
40	        Assert.Equal(variantKinds, dispatched);
41	
42	        var enumKinds = Defs["block"]!["properties"]!["kind"]!["enum"]!.AsArray()
43	            .Select(k => k!.GetValue<string>()).OrderBy(k => k).ToArray();
44	        Assert.Equal(variantKinds, enumKinds);
45	    }
46	
47	    [Fact]
48	    public void Effect_dispatch_covers_every_effect_type()
49	    {
50	        var variantTypes = Defs.Where(d => d.Key.StartsWith("effect_"))
51	            .Select(d => d.Key["effect_".Length..]).OrderBy(t => t).ToArray();
52	        Assert.Equal(
53	            new[] { "createForEach", "createRecord", "email", "enrich", "notify", "updateRecord", "webhook" },
54	            variantTypes);
55	
56	        var dispatched = Defs["effect"]!["allOf"]!.AsArray()
57	            .Select(branch => branch?["if"]?["properties"]?["type"]?["const"]?.GetValue<string>())
58	            .Where(t => t is not null)
59	            .OrderBy(t => t)
60	            .ToArray();
61	        Assert.Equal(variantTypes, dispatched);
62	
63	        var enumTypes = Defs["effect"]!["properties"]!["type"]!["enum"]!.AsArray()
64	            .Select(t => t!.GetValue<string>()).OrderBy(t => t).ToArray();
65	        Assert.Equal(variantTypes, enumTypes);
66	    }
67	
68	    [Fact]
69	    public void UnevaluatedProperties_never_appears()
70	    {
71	        var offenders = new List<string>();
72	        Walk(Schema, "$", offenders);
73	        Assert.Empty(offenders);
74	
75	        static void Walk(JsonNode? node, string path, List<string> offenders)
76	        {
77	            switch (node)
78	            {
79	                case JsonObject o:
80	                    foreach (var (k, v) in o)
81	                    {
82	                        if (k == "unevaluatedProperties") offenders.Add(path);
83	                        Walk(v, $"{path}.{k}", offenders);
84	                    }
85	                    break;
86	                case JsonArray a:
87	                    for (var i = 0; i < a.Count; i++) Walk(a[i], $"{path}[{i}]", offenders);
88	                    break;
89	            }
90	        }
91	    }
92	
93	    [Fact]
94	    public void Every_local_ref_resolves_and_no_ref_is_external()
95	    {
96	        var missing = new List<string>();
97	        Walk(Schema, "$", missing);
98	        Assert.Empty(missing);
99	
100	        void Walk(JsonNode? node, string path, List<string> missing)
101	        {
102	            switch (node)
103	            {
104	                case JsonObject o:
105	                    foreach (var (k, v) in o)
106	                    {
107	                        if (k == "$ref" && v is JsonValue val
108	                            && val.TryGetValue<string>(out var r))
109	                        {
110	                            const string prefix = "#/$defs/";
111	                            if (!r.StartsWith(prefix) || !Defs.ContainsKey(r[prefix.Length..]))
112	                                missing.Add($"{path}: {r}");
113	                        }
114	                        else Walk(v, $"{path}.{k}", missing);
115	                    }
116	                    break;
117	                case JsonArray a:
118	                    for (var i = 0; i < a.Count; i++) Walk(a[i], $"{path}[{i}]", missing);
119	                    break;
120	            }
121	        }
122	    }
123	}
