/// to its own repository. If this throws in a fresh clone, the submodule is not checked out:
/// <c>git submodule update --init</c>. It is deliberately still an anchor on a FILE rather than
/// on the submodule directory, which exists but is empty in exactly that case.</para></summary>
public static string RepoRoot()
{
    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "oss", "cordango", "schemas", "app-definition.schema.json")))
        dir = dir.Parent;
    return dir?.FullName ?? throw new InvalidOperationException(
        "repo root not found from " + AppContext.BaseDirectory +
        " — if oss/cordango is empty, run `git submodule update --init`");
}

