import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import { fileURLToPath, URL } from 'node:url'

// Same rationale as web/vite.config.js: bind-mount file events are unreliable on Windows/macOS
// Docker, so HMR needs polling in the container and native watching everywhere else.
const usePolling = process.env.VITE_USE_POLLING === 'true'

// The editor is a STANDALONE dev tool (it will be embedded in the developer/docs site later), but it
// is not a copy of anything: it reads the real, composed contract straight out of ../schema, so a
// schema change shows up here on the next reload with no sync step.
export default defineConfig({
  plugins: [vue()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
      '@schema': fileURLToPath(new URL('../schema', import.meta.url)),
      // Block introspection shared with the runtime app — ONE derivation of the contract, two hosts.
      // It lives in web/ because that is the shipped product and its container mounts only ./web;
      // this editor is a dev tool run on the host, and already reaches out for @schema.
      '@blockspec': fileURLToPath(new URL('../web/src/blockspec', import.meta.url)),
      '@reference': fileURLToPath(new URL('../exploration/reference', import.meta.url)),
    },
  },
  // ../schema and ../exploration live outside the project root; Vite must be allowed to serve them.
  server: {
    host: true,
    port: 5174,
    fs: { allow: ['..'] },
    watch: usePolling ? { usePolling: true, interval: 300 } : undefined,
  },
  optimizeDeps: { include: ['monaco-editor'] },
})

