#!/usr/bin/env python3
"""Lint a demo seed spec against its app definition — catches the mistakes that would otherwise
only surface as 400s halfway through a live load.

    python demo/check_seed.py demo/seed/invoicing.seed.json [more ...]

Checks: app resolves to an appdef; entities/fields exist; select values are legal options (process
states for a governed status field); required non-computed fields are present; computed and known
auto-owner fields are NOT set; references use @tokens; date/datetime values are tokens or ISO;
actAs is a known Cordango firstname; @entity:key targets are defined earlier in the spec, and
@app.entity:key targets name a real app+entity whose spec defines that key (pass both specs in one
invocation for the key half to be checked).
Exit 1 on any error.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
REF = ROOT / "exploration" / "reference"
# Core apps ship with the platform rather than living in the reference suite, but their seed specs
# need linting exactly the same way.
CORE = ROOT / "schema" / "core"

PEOPLE = {"mara", "clara", "henrik", "ben", "sofia", "emma", "jonas", "elif", "tomas", "yuki",
          "marta", "priya", "lukas", "ava", "milan", "lea", "noah", "david", "ines", "felix",
          "hannah", "omar", "julia", "nina"}
AUTO_OWNER = re.compile(r"(^|_)(created|updated)_by$|_by$|^owner$")
DATE_TOKEN = re.compile(r"^(\{T([+-]\d+)?\}|\{M[+-]\d+:\d{1,2}\}|\{NOW\}|\d{4}-\d{2}-\d{2}([T ].*)?)$")


def appdefs() -> dict:
    out = {}
    for f in REF.glob("*.appdef.json"):
        d = json.loads(f.read_text(encoding="utf-8"))
        out[d["key"]] = d
    # Latest shipped version of each core app (v1, v2, … — the last one wins).
    for f in sorted(CORE.glob("*.v*.json")):
        d = json.loads(f.read_text(encoding="utf-8"))
        out[d["key"]] = d
    return out


def lint(spec_path: Path, defs: dict, foreign: dict | None = None) -> list[str]:
    errors: list[str] = []
    foreign = foreign or {}
    spec = json.loads(spec_path.read_text(encoding="utf-8"))
    app = defs.get(spec.get("app", ""))
    if app is None:
        return [f"unknown app '{spec.get('app')}'"]

    entities = {e["key"]: e for e in app.get("entities", [])}
    states = {p["entity"]: [s["key"] for s in p.get("states", [])] for p in app.get("processes", [])}
    status_field = {p["entity"]: p.get("stateField") for p in app.get("processes", [])}
    seen: dict[str, set] = {}

    for block in spec.get("entities", []):
        ekey = block.get("entity", "?")
        e = entities.get(ekey)
        w = f"{spec_path.name}/{ekey}"
        if e is None:
            errors.append(f"{w}: unknown entity")
            continue
        fields = {f["key"]: f for f in e.get("fields", [])}
        kf = block.get("keyField")
        if kf and kf not in fields:
            errors.append(f"{w}: keyField '{kf}' is not a field")
        seen.setdefault(ekey, set())
        for i, rec in enumerate(block.get("records", [])):
            rw = f"{w}[{i}]"
            if rec.get("_key"):
                seen[ekey].add(rec["_key"])
            act = rec.get("actAs")
            if act is not None and act not in PEOPLE:
                errors.append(f"{rw}: actAs '{act}' is not a Cordango firstname")
            for k, v in rec.items():
                if k in ("_key", "actAs"):
                    continue
                f = fields.get(k)
                if f is None:
                    errors.append(f"{rw}: unknown field '{k}'")
                    continue
                if "computed" in f:
                    errors.append(f"{rw}: '{k}' is computed — the server derives it")
                if AUTO_OWNER.search(k) and f.get("type") == "reference" and f.get("targetApp") == "platform":
                    errors.append(f"{rw}: '{k}' is an auto-owner field — use actAs instead")
                t = f.get("type")
                if t in ("select",):
                    legal = [o["value"] for o in f.get("options", [])]
                    if not legal and status_field.get(ekey) == k:
                        legal = states.get(ekey, [])
                    if legal and v not in legal:
                        errors.append(f"{rw}: '{k}' = '{v}' not in {legal}")
                elif t in ("date", "datetime"):
                    if not (isinstance(v, str) and DATE_TOKEN.match(v)):
                        errors.append(f"{rw}: '{k}' = '{v}' is not a date token/ISO date")
                elif t == "reference":
                    if not (isinstance(v, str) and v.startswith("@")):
                        errors.append(f"{rw}: '{k}' should be an @token reference")
                    elif v.startswith("@person:"):
                        if v.split(":", 1)[1] not in PEOPLE:
                            errors.append(f"{rw}: {v} is not a known person")
                    elif "." in v.split(":", 1)[0]:
                        # Cross-app: the field must SAY so, and the target must be a real entity of
                        # that app. A local-looking token pointing at another app's key is the
                        # mistake this catches — it would resolve to nothing at load time.
                        tgt, _, key = v[1:].partition(":")
                        app_key, _, ent = tgt.partition(".")
                        if f.get("targetApp") != app_key:
                            errors.append(f"{rw}: '{k}' targets '{f.get('targetApp') or 'this app'}' "
                                          f"but {v} names '{app_key}'")
                        elif app_key not in defs:
                            errors.append(f"{rw}: {v} names unknown app '{app_key}'")
                        elif ent not in {e["key"] for e in defs[app_key].get("entities", [])}:
                            errors.append(f"{rw}: {v} names unknown entity '{ent}' in '{app_key}'")
                        elif tgt in foreign and key not in foreign[tgt]:
                            errors.append(f"{rw}: {v} — '{key}' is not a _key in the {app_key} seed spec")
                    else:
                        tgt, _, key = v[1:].partition(":")
                        if f.get("targetApp"):
                            errors.append(f"{rw}: '{k}' targets app '{f['targetApp']}', so {v} must be "
                                          f"written '@{f['targetApp']}.{tgt}:{key}'")
                        elif tgt not in entities:
                            errors.append(f"{rw}: {v} targets unknown entity '{tgt}'")
                        elif key not in seen.get(tgt, set()):
                            errors.append(f"{rw}: {v} — '{key}' not defined earlier in the spec")
                elif t in ("integer", "decimal", "money"):
                    if not isinstance(v, (int, float)):
                        errors.append(f"{rw}: '{k}' should be a number, got {type(v).__name__}")
                elif t == "boolean":
                    if not isinstance(v, bool):
                        errors.append(f"{rw}: '{k}' should be a boolean")
            for fk, f in fields.items():
                if f.get("required") and "computed" not in f and fk not in rec \
                        and not AUTO_OWNER.search(fk) \
                        and not (status_field.get(ekey) == fk):
                    errors.append(f"{rw}: required field '{fk}' missing")
    return errors


def foreign_keys(paths: list[Path]) -> dict:
    """'<app>.<entity>' -> the _keys that spec defines, so a cross-app reference can be checked
    against the spec that actually creates the row."""
    out: dict[str, set] = {}
    for p in paths:
        try:
            spec = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            continue
        for block in spec.get("entities", []):
            keys = {r["_key"] for r in block.get("records", []) if r.get("_key")}
            out[f"{spec.get('app')}.{block.get('entity')}"] = keys
    return out


def main() -> None:
    defs = appdefs()
    paths = [Path(a) for a in sys.argv[1:]]
    foreign = foreign_keys(paths)
    bad = False
    for arg in sys.argv[1:]:
        errs = lint(Path(arg), defs, foreign)
        if errs:
            bad = True
            print(f"INVALID {arg}:")
            for e in errs[:60]:
                print(f"  {e}")
            if len(errs) > 60:
                print(f"  ... and {len(errs) - 60} more")
        else:
            print(f"OK      {arg}")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()

