"""S2b: copy AppBuilder.Definition + AppBuilder.Cord into oss/cordango/src/Cordango.Compiler
and rewrite their namespaces. Copies only; the parent-side delete is a separate step."""
import io, os, re, shutil, glob

SEP = chr(92)
DEST = 'oss/cordango/src/Cordango.Compiler'

def norm(p):
    return p.replace(SEP, '/')

def sources(root):
    out = []
    for p in glob.glob(root + '/**/*.cs', recursive=True):
        n = norm(p)
        if '/obj/' in n or '/bin/' in n:
            continue
        out.append(p)
    return sorted(out)

# Longest-first so the Blueprints sub-namespace is rewritten before its parent.
RENAMES = [
    ('AppBuilder.Definition.Blueprints', 'Cordango.Definition.Blueprints'),
    ('AppBuilder.Definition',            'Cordango.Definition'),
    ('AppBuilder.Cord',                  'Cordango.Cord'),
]

def rewrite(text):
    for old, new in RENAMES:
        text = re.sub(r'\b' + re.escape(old) + r'\b', new, text)
    return text

copied = 0
for root, sub in (('backend/AppBuilder.Definition', 'Definition'),
                  ('backend/AppBuilder.Cord', 'Cord')):
    for p in sources(root):
        rel = norm(os.path.relpath(p, root))
        dst = os.path.join(DEST, sub, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        t = io.open(p, encoding='utf-8-sig').read()
        io.open(dst, 'w', encoding='utf-8', newline='').write(rewrite(t))
        copied += 1

print('copied and rewritten:', copied, 'files')

# Report any AppBuilder.* left in the copies (should be none apart from prose about the old repo).
leftovers = []
for p in glob.glob(DEST + '/**/*.cs', recursive=True):
    t = io.open(p, encoding='utf-8').read()
    for m in re.finditer(r'AppBuilder[\w.]*', t):
        leftovers.append((norm(os.path.relpath(p, DEST)), m.group(0)))
if leftovers:
    print()
    print('remaining AppBuilder references in the copies:')
    seen = {}
    for f, tok in leftovers:
        seen.setdefault(tok, []).append(f)
    for tok in sorted(seen):
        print('   ', tok, '->', len(seen[tok]), 'occurrence(s), e.g.', seen[tok][0])
else:
    print('no AppBuilder references remain in the copies')

