using System.Reflection;
using Cordango.Cord;
using AppBuilder.TestCorpus;

namespace AppBuilder.Cord.Tests;

/// <summary>
/// Rule 0, asserted rather than remembered.
///
/// <para><c>Cordango.Cord</c> is meant to be liftable into a standalone open-source repository as a
/// copy rather than an untangle. That property has a short half-life: it survives exactly as long as
/// nobody needs "just one thing" from Platform. The failure is silent and cheap at the time — a
/// <c>ProjectReference</c> is one line, and everything still builds — and it is only discovered when
/// somebody tries to extract the library and finds it welded to a tenant store.</para>
///
/// <para>Same argument, and the same shape, as
/// <c>AppBuilder.Api.Tests/ServiceBoundaryTests.cs</c>, which keeps the worker from referencing the
/// API. This one additionally checks the COMPILED assembly, because a csproj assertion alone can be
/// satisfied while a transitive reference smuggles the dependency in anyway.</para>
/// </summary>
public class BoundaryTests
{
    /// <summary>What Cord may be built on. Not a style preference — every entry here is either the
    /// framework, the schema library Cord lowers to, or something that library already brought.</summary>
    private static readonly string[] Allowed =
    [
        "Cordango.Definition",
        "JsonSchema.Net",
        "Json.More",
        "Json.Pointer",
        "netstandard",
        "System.Runtime",
    ];

    /// <summary>The concerns that would end the extraction claim if any of them arrived. Named
    /// explicitly so a failure says WHICH boundary was crossed instead of "unexpected reference".</summary>
    private static readonly string[] Forbidden =
    [
        "AppBuilder.Generator",
        "AppBuilder.Platform",
        "AppBuilder.Runtime",
        "AppBuilder.ControlPlane",
        "AppBuilder.Localization",
        "AppBuilder.Api",
        "AppBuilder.Worker",
        "Microsoft.EntityFrameworkCore",
        "Npgsql",
    ];

    private static Assembly Cord => typeof(CordApp).Assembly;

    [Fact]
    public void Cord_references_nothing_outside_the_allowed_set()
    {
        var unexpected = Cord.GetReferencedAssemblies()
            .Select(a => a.Name ?? "")
            .Where(n => !Allowed.Any(ok => n == ok || n.StartsWith(ok + ".", StringComparison.Ordinal)))
            .Where(n => !n.StartsWith("System.", StringComparison.Ordinal) && n != "System")
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToList();

        Assert.True(unexpected.Count == 0,
            "Cordango.Cord must stay independently extractable (rule 0). Unexpected reference(s): "
            + string.Join(", ", unexpected)
            + ". If one of these is genuinely needed, the answer is almost always an adapter in "
            + "AppBuilder.Generator, not a reference here.");
    }

    [Fact]
    public void Cord_references_none_of_the_forbidden_concerns()
    {
        var names = Cord.GetReferencedAssemblies().Select(a => a.Name ?? "").ToHashSet(StringComparer.Ordinal);
        foreach (var banned in Forbidden)
            Assert.False(names.Contains(banned),
                $"Cordango.Cord references {banned}. The dependency direction is Generator -> Cord, "
                + "never the reverse, and persistence/hosting never reach Cord at all.");
    }

    [Fact]
    public void The_csproj_declares_exactly_one_project_reference_and_no_packages()
    {
        var csproj = File.ReadAllText(
            Path.Combine(Corpus.RepoRoot(), "backend", "Cordango.Cord", "Cordango.Cord.csproj"));

        // Counted, not merely inspected for absence: a second reference to a permitted project would
        // still be a second dependency to carry out of the door.
        var references = csproj.Split("<ProjectReference").Length - 1;
        Assert.True(references == 1, $"expected exactly one ProjectReference, found {references}");
        Assert.Contains("Cordango.Definition.csproj", csproj);

        // Cord's job is a data-structure transform. A package here is a dependency an OSS consumer
        // would inherit, so the bar is not "is it useful" but "would we ship it".
        Assert.DoesNotContain("<PackageReference", csproj);
    }

    /// <summary>
    /// A tripwire for the concerns most likely to leak in as a TYPE rather than as a reference.
    ///
    /// <para>The reference checks catch a csproj edit. They do not catch someone hand-rolling an
    /// <c>AnthropicToolDefinition</c> record inside Cord with no new dependency at all — which is the
    /// realistic version of this mistake, because the provider shape is just JSON and copying it
    /// looks harmless. Cord may describe its operations; naming a vendor, a tenant or a transport is
    /// where the boundary is.</para>
    /// </summary>
    [Theory]
    [InlineData("Anthropic")]
    [InlineData("Tenant")]
    [InlineData("Blueprint")]
    [InlineData("DbContext")]
    [InlineData("Http")]
    [InlineData("Tool")]
    public void No_cord_type_names_a_concern_that_belongs_to_the_host(string concern)
    {
        var offenders = Cord.GetTypes()
            .Where(t => t.Name.Contains(concern, StringComparison.OrdinalIgnoreCase))
            .Select(t => t.FullName ?? t.Name)
            .ToList();

        Assert.True(offenders.Count == 0,
            $"'{concern}' belongs to the host, not to Cord: {string.Join(", ", offenders)}. "
            + "Tool and provider shapes are an adapter in AppBuilder.Generator.");
    }
}

