using System.Reflection;

namespace AppBuilder.Api.Tests;

/// <summary>
/// The open-source boundary, asserted rather than remembered.
///
/// <para>The projects under <c>oss/</c> are separate git repositories that happen to be checked out
/// inside this one. They are meant to build from a plain public clone with nothing of the platform
/// underneath them, and the dependency direction is one-way:</para>
///
/// <code>
///     AppBuilder (private)  ---->  Cordango (public)
/// </code>
///
/// <para>The reverse costs one line and breaks nothing locally, because from inside this working
/// copy <c>..\..\backend\Something.csproj</c> resolves perfectly. It breaks in the only place that
/// matters and the only place nobody is looking: a clone of the public repository, where that path
/// does not exist. By the time somebody notices, the reference has been there for weeks and the
/// answer is no longer obvious.</para>
///
/// <para>Sibling of <see cref="ServiceBoundaryTests"/>, which keeps the worker from referencing the
/// API, and of <c>Cordango.Compiler.Tests.BoundaryTests</c>, which polices what the compiler itself
/// is allowed to depend on. This one polices the direction between the two repositories.</para>
/// </summary>
public class OssBoundaryTests
{
    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !Directory.Exists(Path.Combine(dir.FullName, "backend")))
            dir = dir.Parent;
        Assert.True(dir is not null, "could not locate the repository root");
        return dir!.FullName;
    }

    private static string OssRoot() => Path.Combine(RepoRoot(), "oss");

    private static IEnumerable<string> OssProjects() =>
        Directory.Exists(OssRoot())
            ? Directory.GetFiles(OssRoot(), "*.csproj", SearchOption.AllDirectories)
                .Where(p => !p.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}")
                         && !p.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}"))
            : [];

    [Fact]
    public void The_submodules_are_checked_out()
    {
        // Not a boundary rule, but the first thing to know when the rest of this class is silent:
        // an empty submodule makes every check below vacuously pass.
        Assert.True(File.Exists(Path.Combine(OssRoot(), "cordango", "schemas", "app-definition.schema.json")),
            "oss/cordango looks empty — the submodule is not checked out");
        Assert.NotEmpty(OssProjects());
    }

    [Fact]
    public void No_open_source_project_reaches_back_into_the_platform()
    {
        var offenders = new List<string>();
        foreach (var p in OssProjects())
        {
            var text = File.ReadAllText(p);
            if (text.Contains("backend\\", StringComparison.OrdinalIgnoreCase)
                || text.Contains("backend/", StringComparison.OrdinalIgnoreCase)
                || text.Contains("AppBuilder.", StringComparison.Ordinal))
                offenders.Add(Path.GetRelativePath(RepoRoot(), p));
        }

        Assert.True(offenders.Count == 0,
            "these open-source projects name the private repository: " + string.Join(", ", offenders)
            + ". The dependency direction is AppBuilder -> Cordango, never the reverse; a public "
            + "clone has no backend/ to resolve against.");
    }

    [Fact]
    public void No_open_source_assembly_references_a_platform_assembly()
    {
        // The csproj check catches the edit. This catches the same mistake arriving transitively,
        // which a text search over one file cannot see.
        var loaded = AppDomain.CurrentDomain.GetAssemblies()
            .Where(a => (a.GetName().Name ?? "").StartsWith("Cordango.", StringComparison.Ordinal))
            .ToList();

        Assert.NotEmpty(loaded);

        var offenders = loaded
            .SelectMany(a => a.GetReferencedAssemblies()
                .Select(r => (Owner: a.GetName().Name ?? "", Ref: r.Name ?? "")))
            .Where(x => x.Ref.StartsWith("AppBuilder.", StringComparison.Ordinal))
            .Select(x => $"{x.Owner} -> {x.Ref}")
            .Distinct()
            .OrderBy(x => x, StringComparer.Ordinal)
            .ToList();

        Assert.True(offenders.Count == 0,
            "open-source assemblies reference the platform: " + string.Join(", ", offenders));
    }
}

