11	/// <param name="App">The assembled model. Null when the files could not be read as one.</param>
12	/// <param name="Files">What was on disk, app-relative path (without the extension) → exact bytes.
13	/// Kept so a write can skip files that already say the right thing, which is what makes a
14	/// one-aggregate change produce a one-file diff.</param>
