21	    string Path,
22	    string Directory,
23	    CordApp? App,
24	    IReadOnlyDictionary<string, string> Files,
25	    IReadOnlyList<string> Problems,
26	    IReadOnlySet<string>? LegacyPaths = null)
27	{
