39	/// repo-relative in <see cref="Written"/>.</summary>
40	public sealed record FileDiff(
41	    string AppPath,
42	    IReadOnlyList<string> WrittenPaths,
43	    IReadOnlyList<string> DeletedPaths)
44	{
45	    public IEnumerable<string> Written => WrittenPaths.Select(p => $"{AppPath}/{p}{AppFolder.Extension}");
46	    public IEnumerable<string> Deleted => DeletedPaths.Select(p => $"{AppPath}/{p}{AppFolder.Extension}");
47	    public bool Empty => WrittenPaths.Count == 0 && DeletedPaths.Count == 0;
48	}
49	
50	/// <summary>
51	/// The filesystem half of the workspace: <c>.cordango.yaml</c> files in, <see cref="CordApp"/> out, and
52	/// back.
53	///
54	/// <para><b>Three layers, and this one owns only the outer.</b>
55	/// <see cref="CordSource"/> owns the FORMAT — which aggregates get files, what they are called and
56	/// what goes in them — and is pure, so it travels with the portable library.
57	/// <see cref="Yaml"/> owns the SYNTAX. This owns the filesystem: which bytes are on disk, what
58	/// changed, and writing it back without leaving half a file behind.</para>
59	/// </summary>
