63	    /// it — swapping the syntax is a change here and in <see cref="Yaml"/>, nowhere else.</summary>
64	    public const string Extension = ".cordango.yaml";
65	
66	    /// <summary>What app source was called while the command was still called <c>cord</c>.
67	    ///
68	    /// <para>Read, never written. Files are keyed by their aggregate path rather than by their
69	    /// filename, so a pre-rename workspace loads into exactly the same model and the first
70	    /// <see cref="Save"/> writes the aggregate under its current name and deletes the old file.
71	    /// Leaving both would mean one aggregate with two files on disk, and the next load would read
72	    /// whichever the filesystem enumerated last.</para></summary>
73	    public const string LegacyExtension = ".cord.yaml";
74	
75	    /// <summary>
76	    /// Reads one app directory.
77	    ///
78	    /// <para>A problem is never thrown. Somebody editing files gets them wrong routinely, and the
79	    /// useful answer is "these three files are wrong" rather than one exception naming the first.</para>
80	    /// </summary>
81	    public static LoadedApp Load(string root, string appPath)
82	    {
83	        var directory = System.IO.Path.GetFullPath(
84	            System.IO.Path.Combine(root, appPath.Replace('/', System.IO.Path.DirectorySeparatorChar)));
