101	            .ToList();
102	
103	        foreach (var file in onDisk)
104	        {
105	            // `.cordango/` is the BUILD directory and must never be read as source. It lives at the
106	            // workspace root so this cannot normally happen, but a nested one would turn yesterday's
107	            // build output into today's input. The pre-rename name is skipped for the same reason.
108	            var relative = System.IO.Path.GetRelativePath(directory, file).Replace('\\', '/');
109	            if (relative.StartsWith(".cordango/", StringComparison.Ordinal)
110	                || relative.StartsWith(".cord/", StringComparison.Ordinal)) continue;
111	
112	            var suffix = relative.EndsWith(Extension, StringComparison.Ordinal)
113	                ? Extension : LegacyExtension;
114	            var key = relative[..^suffix.Length];
115	            if (suffix == LegacyExtension) legacy.Add(key); else legacy.Remove(key);
116	            string text;
117	            try
118	            {
119	                text = File.ReadAllText(file, Yaml.Encoding);
120	            }
121	            catch (IOException ex)
122	            {
123	                problems.Add($"{appPath}/{relative}: unreadable ({ex.Message})");
124	                continue;
125	            }
126	
127	            contents[key] = text;
128	
129	            var (document, error) = Yaml.Read(text);
130	            if (document is null) problems.Add($"{appPath}/{relative}: {error}");
131	            else documents.Add(new CordSourceFile(key, document));
132	        }
133	
134	        if (documents.Count == 0 && problems.Count == 0)
135	            return new LoadedApp(appPath, directory, null, contents,
136	                [$"{appPath}: no {Extension} files — an app needs at least "
137	                    + $"{CordSource.AppFile}{Extension}"]);
138	
139	        var (app, sourceProblems) = CordSource.Read(documents);
140	        problems.AddRange(sourceProblems.Select(p => $"{appPath}/{p}"));
141	
142	        return new LoadedApp(appPath, directory, problems.Count == 0 ? app : null, contents, problems, legacy);
143	    }
144	
145	    /// <summary>
146	    /// Writes the app back as canonical files, touching only what changed.
147	    ///
148	    /// <para><b>Write the whole app, save the difference.</b> Tracking which aggregate an operation
149	    /// touched and writing only that file would be a second implementation of
