7	[assembly: CollectionBehavior(DisableTestParallelization = true)]
8	
9	namespace Cordango.Cli.Tests;
10	
11	/// <summary>
12	/// A real workspace in a temporary directory, with the process pointed at it and the console
13	/// captured — so a test drives the same entry point a user does rather than a rearranged copy of it.
14	/// </summary>
15	public sealed class Sandbox : IDisposable
16	{
17	    private readonly string _previousDirectory = Directory.GetCurrentDirectory();
18	    private readonly TextWriter _previousOut = Console.Out;
19	    private readonly TextWriter _previousError = Console.Error;
20	
21	    private readonly string? _previousConfigDir =
22	        Environment.GetEnvironmentVariable(Remote.Credentials.DirectoryVariable);
23	
24	    public Sandbox()
25	    {
26	        Root = Path.Combine(Path.GetTempPath(), "cord-tests", Path.GetRandomFileName());
27	        Directory.CreateDirectory(Root);
28	        Directory.SetCurrentDirectory(Root);
29	
30	        // Credentials go inside the sandbox, never into the developer's real profile. Without this
31	        // a `logout --all` in a test would sign the person running it out of their own instances.
32	        ConfigDirectory = Path.Combine(Root, ".cord-config");
33	        Environment.SetEnvironmentVariable(Remote.Credentials.DirectoryVariable, ConfigDirectory);
34	    }
35	
36	    public string Root { get; }
37	
38	    /// <summary>Where this sandbox's <c>credentials.json</c> lives.</summary>
39	    public string ConfigDirectory { get; }
40	
41	    /// <summary>Everything the last command wrote to stdout.</summary>
42	    public string Out { get; private set; } = "";
43	
44	    /// <summary>Everything it wrote to stderr — where human-readable failures go.</summary>
45	    public string Error { get; private set; } = "";
46	
47	    /// <summary>Runs a command exactly as <c>Program</c> would, and captures both streams.</summary>
48	    public int Run(params string[] argv)
49	    {
50	        var stdout = new StringWriter();
51	        var stderr = new StringWriter();
52	        Console.SetOut(stdout);
53	        Console.SetError(stderr);
54	
55	        try
56	        {
57	            var args = Args.Parse(argv);
58	            var output = new Output(args.Json);
59	
60	            return args.Command switch
61	            {
62	                "new" => Commands.NewCommand.Run(args, output),
63	                "add app" => Commands.AddAppCommand.Run(args, output),
64	                "check" => Commands.CheckCommand.Run(args, output),
65	                "build" => Commands.BuildCommand.Run(args, output),
66	                "inspect" => Commands.InspectCommand.Run(args, output),
67	                "vocabulary" => Commands.VocabularyCommand.Run(args, output),
68	                "apply" => Commands.ApplyCommand.Run(args, output),
69	                "fmt" => Commands.FmtCommand.Run(args, output),
70	                "doctor" => Commands.DoctorCommand.Run(args, output),
71	                "version" => Commands.VersionCommand.Run(output),
72	                "logout" => Commands.LogoutCommand.Run(args, output),
73	                // The connected commands are async. Only their OFFLINE refusals are exercised here —
74	                // "not signed in", "no instance bound" — which is everything that happens before the
75	                // first socket. A test that reached the network would be testing an instance.
76	                "whoami" => Commands.WhoamiCommand.RunAsync(args, output, default).GetAwaiter().GetResult(),
77	                "publish" => Commands.PublishCommand.RunAsync(args, output, default).GetAwaiter().GetResult(),
78	                "login" => Commands.LoginCommand.RunAsync(args, output, default).GetAwaiter().GetResult(),
79	                var unknown => throw new InvalidOperationException($"the test called '{unknown}'"),
80	            };
81	        }
82	        finally
83	        {
84	            Out = stdout.ToString();
85	            Error = stderr.ToString();
86	            Console.SetOut(_previousOut);
87	            Console.SetError(_previousError);
88	        }
89	    }
