91	    /// <summary>Runs with <c>--json</c> and parses the envelope — the agent-facing surface.</summary>
92	    public (int Exit, JsonObject Payload) RunJson(params string[] argv)
93	    {
94	        var exit = Run([.. argv, "--json"]);
95	        return (exit, (JsonObject)JsonNode.Parse(Out)!);
96	    }
97	
98	    public string Path_(params string[] parts) => System.IO.Path.Combine([Root, .. parts]);
99	
100	    /// <summary>Every <c>.cordango</c> file in the workspace, app-relative path → exact bytes. The
101	    /// comparison behind "a refused change leaves the files byte-identical".</summary>
102	    public Dictionary<string, string> Snapshot()
103	    {
104	        return Directory
105	            .EnumerateFiles(Root, "*.cordango.yaml", SearchOption.AllDirectories)
106	            .ToDictionary(
107	                f => System.IO.Path.GetRelativePath(Root, f).Replace('\\', '/'),
108	                File.ReadAllText,
109	                StringComparer.Ordinal);
110	    }
111	
112	    public void Write(string relativePath, string content)
113	    {
114	        var path = Path_(relativePath.Replace('/', System.IO.Path.DirectorySeparatorChar));
115	        Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path)!);
116	        File.WriteAllText(path, content);
117	    }
118	
119	    public void Dispose()
120	    {
121	        Console.SetOut(_previousOut);
122	        Console.SetError(_previousError);
123	        Directory.SetCurrentDirectory(_previousDirectory);
124	        Environment.SetEnvironmentVariable(Remote.Credentials.DirectoryVariable, _previousConfigDir);
125	
126	        try
127	        {
128	            Directory.Delete(Root, recursive: true);
129	        }
130	        catch (IOException)
131	        {
132	            // A leftover temp directory is not worth failing a green test over.
133	        }
134	    }
