[Fact]
public void The_hand_authored_applications_are_written_out()
{
    var apps = new (string File, CordApp Identity, (string Ops, IReadOnlyCollection<string> Allowed)[] Calls)[]
    {
        ("expense-approval.appdef.json",
         new CordApp(Key: "cord_expense_approval", Name: "Expense approval (Cord)", Version: "1.0.0"),
         [(ExpenseDomain, CordOps.DomainOpNames), (ExpenseBehaviour, CordOps.BehaviourOpNames),
          (ExpenseScreens, CordOps.UiOpNames)]),
        ("budget-model.appdef.json",
         new CordApp(Key: "cord_budget_model", Name: "Budget model (Cord)", Version: "1.0.0"),
         [(BudgetDomain, CordOps.DomainOpNames), (BudgetBehaviour, CordOps.BehaviourOpNames),
          (BudgetScreens, CordOps.UiOpNames)]),
        ("crm-pipeline.appdef.json",
         new CordApp(Key: "cord_crm_pipeline", Name: "Sales pipeline (Cord)", Version: "1.0.0"),
         [(CrmDomain, CordOps.DomainOpNames), (CrmBehaviour, CordOps.BehaviourOpNames),
          (CrmScreens, CordOps.UiOpNames)]),
    };

    var dir = Path.Combine(Corpus.RepoRoot(), "exploration", "cord", "apps");
    Directory.CreateDirectory(dir);

    foreach (var (file, identity, calls) in apps)
    {
        var app = identity;
        foreach (var (ops, allowed) in calls)
        {
            var prepared = CordTransaction.Prepare(app, JsonNode.Parse(ops), allowed);
            Assert.True(prepared.Ok, $"{file}: {string.Join("; ", prepared.Errors)}");
            app = prepared.Next;
        }

        var definition = CordLower.Lower(app);
        var result = CandidateValidator.Run(definition, "app-cord-export", At);
        foreach (var e in result.Errors) output.WriteLine($"{file}: {e}");
        Assert.True(result.Valid, $"{file} must be publishable to be worth writing out");

