1	// Deliberately NOT Cordango.Compiler.Tests: this file is compiled into more than one test project,
2	// and a namespace naming one of them would read as a dependency on it from the others.
3	namespace Cordango.TestCorpus;
4	
5	/// <summary>
6	/// The one definition of "the corpus", shared by every suite that has to hold itself against real
7	/// definitions.
8	///
9	/// <para>It lives in this project because the gate is what the corpus was first assembled to protect,
10	/// but it is <b>source-linked</b> into the other test projects rather than reached through a project
11	/// reference — a test project referencing another test project drags its fixtures, its
12	/// <c>[MemberData]</c> and its whole dependency set along with it. The file is small and pure on
13	/// purpose; linking a file is cheap, and a second private copy of "which files are the corpus" is
14	/// exactly the drift that lets a new reference app be covered by one suite and silently skipped by
15	/// another.</para>
16	///
17	/// <para>Consumers today: this project (the gate, the union safety net, Cord round-trip and
18	/// coverage) and <c>AppBuilder.Runtime.Tests</c> in the private platform repository, which links
19	/// this same file across the submodule boundary rather than keeping a second list.</para>
20	/// </summary>
21	public static class Corpus
22	{
23	    /// <summary>
24	    /// The root of the Cordango repository, found by walking up from the test binary until the
25	    /// schema is underfoot.
26	    ///
27	    /// <para>Anchored on the schema FILE rather than on <c>.git</c> or a directory name so it still
28	    /// works from a build output nested at an unknown depth — and so it still works when this
29	    /// repository is a submodule, where <c>.git</c> is a file pointing elsewhere and the directory
30	    /// name is whatever the host chose to mount it as.</para>
31	    ///
32	    /// <para>Two shapes, one answer. In a plain clone the schema sits at <c>schemas/</c>; mounted
33	    /// inside the private monorepo it sits at <c>oss/cordango/schemas/</c>. Either way this returns
34	    /// the directory that CONTAINS <c>schemas/</c>, so every path below is written once and means
35	    /// the same thing from both hosts. If it throws while a checkout looks fine, the submodule is
36	    /// present but empty: initialise it.</para>
37	    /// </summary>
38	    public static string RepoRoot()
39	    {
40	        var dir = new DirectoryInfo(AppContext.BaseDirectory);
41	        while (dir is not null)
42	        {
43	            if (HasSchema(dir.FullName)) return dir.FullName;
44	
45	            var mounted = Path.Combine(dir.FullName, "oss", "cordango");
46	            if (HasSchema(mounted)) return mounted;
47	
48	            dir = dir.Parent;
49	        }
50	
51	        throw new InvalidOperationException(
52	            "Cordango repo root not found from " + AppContext.BaseDirectory +
53	            " — if oss/cordango exists but is empty, the submodule is not checked out");
54	
55	        static bool HasSchema(string root) =>
56	            File.Exists(Path.Combine(root, "schemas", "app-definition.schema.json"));
57	    }
58	
59	    /// <summary>The maintained corpus: the hand-authored reference apps + the canonical CRM example.
60	    /// These are asserted FULLY gate-clean.</summary>
61	    public static TheoryData<string> MaintainedDefinitions()
62	    {
63	        var root = RepoRoot();
64	        var data = new TheoryData<string>();
65	        foreach (var p in Directory.GetFiles(Path.Combine(root, "tests", "corpus", "reference"), "*.appdef.json"))
66	            data.Add(p);
67	        data.Add(Path.Combine(root, "tests", "corpus", "crm.appdef.json"));
68	        return data;
69	    }
70	
71	    /// <summary>Every definition in the repo except the deliberately-invalid fixture — the widest
72	    /// net for the structural checks.
73	    ///
74	    /// <para>Enumerated directory by directory rather than by recursing <c>samples/</c>, which also
75	    /// holds the Budget Planner CordSource specimen: its <c>coverage.json</c> is a report, not an
76	    /// application, and a recursive glob would feed it to the gate and fail a structural check with
77	    /// a message about a file nobody thought was a definition.</para></summary>
78	    public static TheoryData<string> AllDefinitions()
79	    {
80	        var root = RepoRoot();
81	        var data = new TheoryData<string>();
82	        foreach (var p in Directory.GetFiles(Path.Combine(root, "tests", "corpus", "reference"), "*.appdef.json"))
83	            data.Add(p);
84	        data.Add(Path.Combine(root, "tests", "corpus", "crm.appdef.json"));
85	        foreach (var dir in new[] { "historical", "interactive" })
86	            foreach (var p in Directory.GetFiles(Path.Combine(root, "tests", "fixtures", dir), "*.json"))
87	                data.Add(p);
88	        return data;
89	    }
90	
91	    /// <summary>
92	    /// The maintained corpus plus Budget Planner — every app a semantic authoring layer must be able
93	    /// to represent.
94	    ///
95	    /// <para>Budget Planner is deliberately outside <see cref="MaintainedDefinitions"/>: it is not in
96	    /// the demo suite and is an exploration artifact rather than a demo app. It is also the hardest
97	    /// document in the repo — 12 windowed rollups in both directions and at both scales, four
98	    /// <c>prev()</c> expressions, a series partition, a settings singleton — which makes it the one
99	    /// app no coverage claim may quietly exclude.</para>
100	    /// </summary>
101	    public static TheoryData<string> SemanticCorpus()
102	    {
103	        var data = new TheoryData<string>();
104	        foreach (var p in SemanticPaths()) data.Add(p);
105	        return data;
106	    }
107	
108	    /// <summary>The same set as a plain list. <c>TheoryData</c> is awkward to aggregate over — it is
109	    /// built to be spread across test cases, not summed — and a coverage report needs the whole
