28	    public const string FileName = "cordango.yaml";
29	
30	    /// <summary>What the root manifest was called while the command was still called <c>cord</c>.
31	    ///
32	    /// <para>Read, never written. A workspace created before the rename still opens, and the first
33	    /// <see cref="Save"/> migrates it: the new file is written and this one is deleted, so a
34	    /// checkout never ends up with two manifests where the stale one wins on the next
35	    /// <see cref="Find"/>. Deleting rather than leaving it is the whole point — a second manifest is
36	    /// not a backup, it is a second answer to "which apps are installed".</para></summary>
37	    public const string LegacyFileName = "cord.yaml";
38	
39	    public const int FormatVersion = 1;
40	
41	    /// <summary>The runtime range a fresh workspace declares. Pre-1.0 and deliberately narrow —
42	    /// nothing about this format is promised across a minor bump yet.</summary>
43	    public const string DefaultRuntime = ">=0.1 <0.2";
44	
