46	
47	    /// <summary>
48	    /// Finds the workspace by walking UP from <paramref name="from"/>, so every command works from
49	    /// any descendant directory — which is what lets an agent run `cordango check` from inside
50	    /// `apps/expenses/entities/` without knowing where the root is.
51	    /// </summary>
52	    public static WorkspaceFile? Find(string from, out string? problem)
53	    {
54	        problem = null;
55	        var dir = new DirectoryInfo(System.IO.Path.GetFullPath(from));
56	
57	        while (dir is not null)
58	        {
59	            // Current name first: a directory holding both is one mid-migration, and the new file is
60	            // the authority there.
61	            var candidate = System.IO.Path.Combine(dir.FullName, FileName);
62	            if (File.Exists(candidate)) return Read(candidate, out problem);
63	
64	            var legacy = System.IO.Path.Combine(dir.FullName, LegacyFileName);
65	            if (File.Exists(legacy)) return Read(legacy, out problem);
66	
67	            dir = dir.Parent;
68	        }
69	
70	        return null;
71	    }
72	
73	    public static WorkspaceFile? Read(string path, out string? problem)
74	    {
75	        problem = null;
76	        JsonObject doc;
77	        try
78	        {
79	            var (parsed, error) = Yaml.Read(File.ReadAllText(path, Yaml.Encoding));
80	            if (parsed is null)
81	            {
82	                problem = $"{path}: {error}";
83	                return null;
84	            }
85	            doc = parsed;
86	        }
87	        catch (IOException ex)
88	        {
89	            problem = $"{path}: unreadable ({ex.Message})";
90	            return null;
91	        }
92	
93	        // An unknown format version is refused rather than tolerated. A newer workspace opened by an
94	        // older CLI would parse — the shape barely changes — and then be materialized back WITHOUT
95	        // whatever the newer version added, which is data loss disguised as a successful command.
96	        // Read as long, not int: YAML has one integer type and the reader produces the widest, so
97	        // an `(int?)` cast throws on a document that is perfectly well formed.
98	        var format = doc["formatVersion"] is JsonValue v && v.TryGetValue<long>(out var declared)
99	            ? declared : 0;
100	        if (format != FormatVersion)
101	        {
102	            problem = $"{path}: formatVersion {format} — this cordango understands {FormatVersion}. "
103	                + "Upgrade cordango, or check out a matching revision of this workspace.";
104	            return null;
105	        }
106	
107	        var apps = (doc["apps"] as JsonArray ?? [])
108	            .OfType<JsonValue>()
109	            .Select(v => v.TryGetValue<string>(out var s) ? s : null)
110	            .OfType<string>()
111	            .ToList();
112	
113	        return new WorkspaceFile(
114	            System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path))!,
115	            (string?)doc["workspaceId"] ?? "",
116	            (string?)doc["name"] ?? "",
117	            (string?)doc["runtime"] ?? DefaultRuntime,
118	            apps);
119	    }
120	
121	    public void Save()
122	    {
123	        var doc = new JsonObject
124	        {
125	            ["formatVersion"] = FormatVersion,
126	            ["workspaceId"] = WorkspaceId,
127	            ["name"] = Name,
128	            ["runtime"] = Runtime,
129	            ["coreApps"] = "default",
130	            ["apps"] = new JsonArray([.. Apps.Select(a => (JsonNode)a!)]),
131	        };
132	
133	        AtomicFile.Write(Path, Yaml.Write(doc));
134	
135	        // Migrate in place: the manifest has just been written under its current name, so a
136	        // leftover pre-rename one is now a stale duplicate rather than history.
137	        var legacy = System.IO.Path.Combine(Root, LegacyFileName);
138	        if (File.Exists(legacy)) File.Delete(legacy);
139	    }
140	
141	    /// <summary>Absolute directory for one registered app path.</summary>
142	    public string DirectoryOf(string appPath) =>
143	        System.IO.Path.GetFullPath(System.IO.Path.Combine(Root, appPath.Replace('/', System.IO.Path.DirectorySeparatorChar)));
144	
145	    /// <summary>
146	    /// A workspace id: ULID-shaped so it sorts by creation and carries no machine identity.
147	    ///
148	    /// <para>Deliberately NOT a GUID — this string ends up in a filesystem path under the user's
149	    /// application-data directory, and Crockford base32 is case-insensitive-safe on the two platforms
150	    /// whose filesystems are, while a GUID's braces and hyphens are noise there.</para>
151	    /// </summary>
152	    public static string NewId(DateTimeOffset now, Func<int, byte[]> randomBytes)
153	    {
154	        const string Alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
155	
156	        var time = now.ToUnixTimeMilliseconds();
157	        var chars = new char[26];
158	        for (var i = 9; i >= 0; i--)
159	        {
160	            chars[i] = Alphabet[(int)(time & 31)];
161	            time >>= 5;
162	        }
163	
164	        var random = randomBytes(16);
165	        for (var i = 0; i < 16; i++) chars[10 + i] = Alphabet[random[i] & 31];
166	
167	        return new string(chars);
168	    }
