import json, glob
for f in sorted(glob.glob('reference/*.appdef.json')) + ['crm.appdef.json', 'budget-planner.appdef.json']:
    d = json.load(open(f, encoding='utf-8'))
    hits = []
    for e in d.get('entities', []):
        if 'series' in e: hits.append('series')
        for fl in e.get('fields', []):
            c = fl.get('computed') or {}
            if 'prev(' in str(c.get('expr', '')): hits.append('prev()')
            r = c.get('rollup') or {}
            if 'window' in r: hits.append('window')
            if 'match' in r: hits.append('match')
    def walk(n):
        out = []
        if isinstance(n, dict):
            if n.get('kind') in ('history', 'relatedApps'): out.append('block:' + n['kind'])
            if n.get('type') == 'enrich' : out.append('effect:enrich')
            for v in n.values(): out += walk(v)
        elif isinstance(n, list):
            for v in n: out += walk(v)
        return out
    hits += walk(d)
    if hits:
        c = {}
        for h in hits: c[h] = c.get(h, 0) + 1
        print('%-28s %s' % (f.split('/')[-1], c))
