        Assert.True(GeneratedFileWriter.Write(Out("one"), a, Draft()).Ok);
        Assert.True(GeneratedFileWriter.Write(Out("two"), b, Draft()).Ok);

        Assert.Equal(Fingerprint(Out("one")), Fingerprint(Out("two")));
