import json, glob, collections
WITHHELD = {'answers','externalEmbed','gantt','history','intake','orgchart','relatedApps','timeline','widgets'}
ARCH = {'history':'CORD2102','relatedApps':'CORD2101'}

for f in sorted(glob.glob('reference/*.appdef.json')) + ['crm.appdef.json','budget-planner.appdef.json']:
    d = json.load(open(f, encoding='utf-8'))
    codes = collections.Counter()
    def walk(n):
        if isinstance(n, dict):
            k = n.get('kind')
            if isinstance(k, str) and k in WITHHELD:
                codes[ARCH.get(k, 'CORD2111:' + k)] += 1
            for v in n.values(): walk(v)
        elif isinstance(n, list):
            for v in n: walk(v)
    for s in ('pages','views'): walk(d.get(s))
    for e in d.get('entities', []):
        if 'series' in e: codes['CORD2104'] += 1
        for fl in e.get('fields', []):
            c = fl.get('computed') or {}
            if 'prev(' in str(c.get('expr','')): codes['CORD2105'] += 1
            r = c.get('rollup') or {}
            if 'window' in r or 'match' in r: codes['CORD2106'] += 1
    name = f.split('/')[-1]
    if not codes:
        print('%-30s FULL PASS' % name)
    else:
        arch = sorted(c for c in codes if not c.startswith('CORD2111'))
        ui = sorted(c.split(':')[1] for c in codes if c.startswith('CORD2111'))
        tag = 'REFUSED  ' if arch else 'UI-PARTIAL'
        print('%-30s %s  arch=%s ui=%s' % (name, tag, arch or '-', ui or '-'))
