/// <summary>
/// Walks only the SCREEN sections, and only reports kinds the schema calls blocks.
///
/// <para>Both halves matter. <c>kind</c> is not exclusively a block property — an entity has one
/// too (<c>collection</c>, <c>config</c>, <c>settings</c>), and <c>settings</c> is spelled the
/// same in both places. Walking the whole document and treating every <c>kind</c> as a block
/// would report a configuration entity as an unsupported screen.</para>
/// </summary>
private static void Blocks(JsonObject definition, GeneratorCapabilities caps, List<Diagnostic> found)
{
    foreach (var section in new[] { "pages", "views" })
        Walk(definition[section], $"$.{section}");

    void Walk(JsonNode? node, string path)
    {
        switch (node)
        {
            case JsonObject o:
                if (Str(o["kind"]) is { } kind && DefinitionVocabulary.BlockKinds.Contains(kind))
                    Block(kind, path, caps, found);
                foreach (var (k, v) in o) Walk(v, $"{path}.{k}");
                break;
            case JsonArray a:
                for (var i = 0; i < a.Count; i++) Walk(a[i], $"{path}[{i}]");
                break;
        }
    }
}

