import json, glob, collections
WITHHELD = {'answers','externalEmbed','gantt','history','intake','orgchart','relatedApps','timeline','widgets'}
ARCH = {'history':'CORD2102','relatedApps':'CORD2101'}

for f in sorted(glob.glob('reference/*.appdef.json')) + ['crm.appdef.json','budget-planner.appdef.json']:
    d = json.load(open(f, encoding='utf-8'))
    codes = collections.Counter()
    def walk(n, path='$', is_entity=False):
        if isinstance(n, dict):
            k = n.get('kind')
            if not is_entity and isinstance(k, str) and k in WITHHELD:
                codes[ARCH.get(k, 'ui:' + k)] += 1
            for kk, v in n.items(): walk(v, path + '.' + kk, False)
        elif isinstance(n, list):
            entities = (path == '$.entities')
            for i, v in enumerate(n): walk(v, path + '[' + str(i) + ']', entities)
    walk(d)
    for e in d.get('entities', []):
        if 'series' in e: codes['CORD2104'] += 1
        for fl in e.get('fields', []):
            c = fl.get('computed') or {}
            if 'prev(' in str(c.get('expr','')): codes['CORD2105'] += 1
            r = c.get('rollup') or {}
            if 'window' in r or 'match' in r: codes['CORD2106'] += 1
    name = f.split('/')[-1].replace('reference\\','')
    arch = sorted({c for c in codes if not c.startswith('ui:')})
    ui = sorted({c[3:] for c in codes if c.startswith('ui:')})
    if not codes: print('%-28s FULL PASS' % name)
    elif not arch: print('%-28s UI-ONLY    %s' % (name, ', '.join(ui)))
    else: print('%-28s REFUSED    %s%s' % (name, ', '.join(arch), ('  + ui: ' + ', '.join(ui)) if ui else ''))
PYEOF

