        what + " is not generated yet. The application still builds — pass --allow-partial-ui to "
             + "replace the screen with a placeholder that says so, and the omission is recorded in "
             + "cordango.build.json";

"""
assert old2 in t
t = t.replace(old2, "")
io.open(p, 'w', encoding='utf-8', newline='').write(t)
