// SPDX-License-Identifier: Apache-2.0
// Copyright (c) Cordango and contributors.
// Part of Cordango, the open application language and compiler: https://github.com/cordango/cordango
// Licensed under the Apache License, Version 2.0. See LICENSE in the repository root.

using System.Text.Json.Nodes;
using Cordango.SourceGen.DotNetVue;
using Cordango.TestCorpus;

namespace Cordango.Compatibility.Tests;

/// <summary>
/// Which real applications the standalone target can build, stated as a table rather than as a
/// hope.
///
/// <para><b>Scope drift is the thing this catches.</b> A capability list is easy to widen by
/// accident — support one more block kind here, relax a check there — and the effect is invisible
/// until somebody generates an application that then does not work. Pinning the EXPECTED refusals,
/// by app and by code, means widening a capability has to be a deliberate edit to this table.</para>
///
/// <para>It runs against the same corpus the gate and the round-trip suites use, so an app added to
/// <c>tests/corpus/reference/</c> is enrolled here automatically and has to be classified.</para>
/// </summary>
public class StandaloneCompatibilityTests
{
    private static readonly GeneratorCapabilities Standalone = new DotNetVueGenerator().Capabilities;

    /// <summary>
    /// Every application that must build with no refusals at all — eight of the fifteen.
    ///
    /// <para>Anything not named in <see cref="Expected"/> lands here, so a new reference app is
    /// enrolled automatically and has to be classified before the suite goes green.</para>
    /// </summary>
    public static TheoryData<string> Buildable()
    {
        var data = new TheoryData<string>();
        foreach (var path in Corpus.SemanticPaths())
            if (!Expected.ContainsKey(Name(path))) data.Add(path);
        return data;
    }

    /// <summary>
    /// The applications that do NOT build clean, and the exact codes each one produces.
    ///
    /// <para><b>Two different kinds of refusal live in this table and they are not equally
    /// serious.</b> CORD2111 alone means the BEHAVIOUR is fully supported and one screen is not
    /// drawn yet — those five applications generate and run today with
    /// <c>--allow-partial-ui</c>, and they leave the tier-B list as those blocks get emitters.
    /// Anything else is architecture: ventures and budget-planner place audit blocks fed by
    /// platform history, and budget-planner additionally carries an ordered series,
    /// <c>prev()</c> expressions and windowed rollups, every one of which needs the recompute
    /// machinery a single-application runtime deliberately does not have.</para>
    /// </summary>
    private static readonly IReadOnlyDictionary<string, string[]> Expected =
        new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            // Screens only. These build with --allow-partial-ui.
            ["helpdesk.appdef.json"] = [DiagnosticCodes.UnsupportedBlock],      // intake, answers
            ["people-hr.appdef.json"] = [DiagnosticCodes.UnsupportedBlock],     // orgchart
            ["sales-crm.appdef.json"] = [DiagnosticCodes.UnsupportedBlock],     // widgets
            ["task-manager.appdef.json"] = [DiagnosticCodes.UnsupportedBlock],  // gantt
            ["time-off.appdef.json"] = [DiagnosticCodes.UnsupportedBlock],      // timeline

            // Architecture.
            ["ventures.appdef.json"] = [DiagnosticCodes.HistoryBlock],
            ["budget-planner.appdef.json"] =
            [
                DiagnosticCodes.HistoryBlock,
                DiagnosticCodes.SeriesEntity,
                DiagnosticCodes.PrevExpression,
                DiagnosticCodes.WindowedRollup,
            ],
        };

    /// <summary>The applications whose only problem is a screen. Named separately because the
    /// difference decides whether somebody can ship: a UI gap is a flag away, and a history block is
    /// a different product.</summary>
    private static readonly IReadOnlySet<string> UiOnly = new HashSet<string>(StringComparer.Ordinal)
    {
        "helpdesk.appdef.json", "people-hr.appdef.json", "sales-crm.appdef.json",
        "task-manager.appdef.json", "time-off.appdef.json",
    };

    public static TheoryData<string> NotBuildable()
    {
        var data = new TheoryData<string>();
        foreach (var name in Expected.Keys) data.Add(name);
        return data;
    }

    [Theory]
    [MemberData(nameof(Buildable))]
    public void The_standalone_target_builds_this_application(string path)
    {
        var found = Validate(path);

        Assert.True(found.Count == 0,
            $"{Name(path)} was expected to build standalone but reported:\n  "
            + string.Join("\n  ", found.Select(d => d.ToString())));
    }

    [Theory]
    [MemberData(nameof(NotBuildable))]
    public void The_standalone_target_refuses_this_application_for_exactly_these_reasons(string name)
    {
        var path = Corpus.SemanticPaths().Single(p => Name(p) == name);
        var codes = Validate(path).Select(d => d.Code).Distinct().OrderBy(c => c, StringComparer.Ordinal);

        // Set equality, not "contains": a refusal that disappears is a capability quietly widened,
        // and one that appears is a capability quietly narrowed. Both are edits somebody should
        // have made here first.
        Assert.Equal(Expected[name].OrderBy(c => c, StringComparer.Ordinal), codes);
    }

    /// <summary>
    /// The screen-only applications must be blocked by NOTHING but screens.
    ///
    /// <para>Stated as its own assertion because it is the claim that matters commercially: their
    /// entities, processes, commands, workflows and permissions are all supported, so
    /// <c>--allow-partial-ui</c> is enough to ship them. If an architectural code ever appears here,
    /// that stops being true and the table above is no longer telling the truth about what the
    /// target can do.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(NotBuildable))]
    public void A_screen_only_refusal_never_hides_an_architectural_one(string name)
    {
        if (!UiOnly.Contains(name)) return;

        var path = Corpus.SemanticPaths().Single(p => Name(p) == name);
        var architectural = Validate(path)
            .Where(d => d.Code != DiagnosticCodes.UnsupportedBlock)
            .ToList();

        Assert.True(architectural.Count == 0,
            $"{name} is listed as a screens-only gap but also reports:\n  "
            + string.Join("\n  ", architectural.Select(d => d.ToString())));
    }

    /// <summary>Every refusal names where it is. A capability message without a JSON path is a
    /// puzzle: "this app uses a history block" is not actionable in a 90 KB document.</summary>
    [Fact]
    public void Every_refusal_points_at_the_definition()
    {
        foreach (var path in Corpus.SemanticPaths())
            foreach (var found in Validate(path))
            {
                Assert.False(string.IsNullOrWhiteSpace(found.JsonPath),
                    $"{Name(path)}: {found.Code} has no path");
                Assert.StartsWith("$.", found.JsonPath, StringComparison.Ordinal);
            }
    }

    /// <summary>Every refusal explains itself. The reason is what separates "we decided not to" from
    /// "we forgot", and a reader cannot tell those apart from a code alone.</summary>
    [Fact]
    public void Every_refusal_carries_a_reason_rather_than_just_a_code()
    {
        foreach (var path in Corpus.SemanticPaths())
            foreach (var found in Validate(path))
                Assert.True(found.Message.Length > 40,
                    $"{Name(path)}: {found.Code} says only '{found.Message}'");
    }

    private static IReadOnlyList<Diagnostic> Validate(string path) =>
        TargetValidator.Validate(
            JsonNode.Parse(File.ReadAllText(path))!.AsObject(), Standalone);

    private static string Name(string path) => Path.GetFileName(path);
}

