        // disk rather than in platform media storage.
        FieldTypes: CapabilitySet.Of(
        [
            "text", "longtext", "email", "url", "phone", "select", "multiselect", "boolean",
            "integer", "decimal", "money", "date", "datetime", "reference", "attachment", "json",
        ]),

