        // named by `targetApp` is a separately installed application, which cannot exist here.
        PlatformTargets: CapabilitySet.Of(
            ["platform", "core_organizations"],
            fallback:
            "this target builds ONE application, so there are no other installed applications to "
            + "reference. Cross-application references are what the platform is for"),

        PlatformEntities: CapabilitySet.Of(
            ["person", "department", "group", "organization", "contact"],
            fallback:
            "this target carries local People, Organizations, Departments and Groups; a platform "
            + "entity outside that set has nothing local to map onto"),

