        // standalone target that cannot build the Budget Planner, and a calculation plane that only
        // works on the hosted product is not the calculation plane being sold.
        SeriesAndPrev: true,

        // Rollups up a reference are a GROUP BY. Windowed and matched rollups are a declarative
        // SUMIFS over a range or across siblings, and they lean on the same cascade.
        WindowedRollups: true);

    public GenerateResult Generate(GenerateRequest request)
    {
        // Honest refusal rather than an empty success. A generator that answered "no files" would
        // produce an empty directory and a build metadata file claiming everything went fine.
        return GenerateResult.Failed(new Diagnostic("CORD2300",
            "the dotnet-vue generator declares its capabilities but does not emit source yet. "
            + "`cordango check --target dotnet-vue` already answers whether an application is "
            + "compatible."));
    }
}

