using System.Text.Json.Nodes;

namespace AppBuilder.Runtime;

/// <summary>How a field may be touched by the caller: read = visible in responses,
/// update = settable on create/update. Absent-from-the-map fields inherit the entity defaults.</summary>
public sealed record FieldRule(bool Read, bool Update);

/// <summary>The caller's effective access to ONE entity — the union of every one of their roles'
/// grants, resolved to entity-level CRUD plus per-field read/update rules. Owner/platform-admin
/// bypass this entirely (they get <see cref="Full"/>); it governs granted, non-owner users only.
/// Pure and immutable — computed by <see cref="PermissionEvaluator"/> from the AppDefinition's
/// <c>roles</c>, so it holds no request/DB state and is trivially testable.</summary>
public sealed class EntityAccess
{
    public bool Create { get; }
    public bool Read { get; }
    public bool Update { get; }
    public bool Delete { get; }

    /// <summary>Per-field overrides (only fields a role narrowed/widened appear here).</summary>
    private readonly IReadOnlyDictionary<string, FieldRule> _fields;

    /// <summary>Command keys this caller may invoke on the entity (deny-by-default). Empty unless a
    /// grant lists commands; <see cref="_allCommands"/> is the ['*'] shortcut / owner-admin bypass.</summary>
    private readonly IReadOnlySet<string> _commands;
    private readonly bool _allCommands;

    public EntityAccess(bool create, bool read, bool update, bool delete,
        IReadOnlyDictionary<string, FieldRule> fields,
        IReadOnlySet<string>? commands = null, bool allCommands = false)
    {
        Create = create; Read = read; Update = update; Delete = delete;
        _fields = fields;
        _commands = commands ?? EmptyCommands;
        _allCommands = allCommands;
    }

    // Declared before the presets below: static fields initialize in textual order, and the presets
    // pass this in — if it came after them it would still be null at their construction.
    private static readonly IReadOnlyDictionary<string, FieldRule> Empty = new Dictionary<string, FieldRule>();
    private static readonly IReadOnlySet<string> EmptyCommands = new HashSet<string>();

    /// <summary>Owner / platform-admin: unrestricted (bypasses role evaluation) — all commands allowed.</summary>
    public static readonly EntityAccess Full = new(true, true, true, true, Empty, allCommands: true);

    /// <summary>No access at all (no relationship / role denies everything).</summary>
    public static readonly EntityAccess None = new(false, false, false, false, Empty);

    /// <summary>The decided default for grant-holders on an app whose definition declares NO roles:
    /// read-only on every entity, no field restrictions, no commands (see the M3 plan).</summary>
    public static readonly EntityAccess ReadOnly = new(false, true, false, false, Empty);

    public bool Allows(string op) => op switch
    {
        "create" => Create,
        "read" => Read,
        "update" => Update,
        "delete" => Delete,
        _ => false,
    };

    public bool CanReadField(string field) => _fields.TryGetValue(field, out var r) ? r.Read : Read;
    public bool CanUpdateField(string field) => _fields.TryGetValue(field, out var r) ? r.Update : Update;

    /// <summary>Field keys whose read is denied — used to strip columns from responses.</summary>
    public IEnumerable<string> HiddenReadFields => _fields.Where(kv => !kv.Value.Read).Select(kv => kv.Key);

    /// <summary>Field keys explicitly locked for writes (a role narrowed them to update:false and no
    /// other role re-opened them) — used to reject create/update payloads that touch them. Keyed off
    /// explicit overrides so a create-capable role can still set ordinary, un-restricted fields.</summary>
    public IEnumerable<string> WriteRestrictedFields => _fields.Where(kv => !kv.Value.Update).Select(kv => kv.Key);

    /// <summary>May the caller invoke this command on the entity? Deny-by-default: true only for
    /// owner/admin (all commands) or when a grant lists the command (or ['*']).</summary>
    public bool CanRunCommand(string commandKey) => _allCommands || _commands.Contains(commandKey);

    /// <summary>The command keys allowed (for the /access map). '*' when every command is allowed.</summary>
    public IReadOnlyCollection<string> AllowedCommands => _allCommands ? new[] { "*" } : _commands.ToArray();
}

/// <summary>Turns AppDefinition <c>roles</c> + the caller's role keys into an <see cref="EntityAccess"/>
/// for a given entity. Pure/deterministic; the API layer supplies the role keys (from grants) and
/// applies the owner/admin bypass and the no-roles default.</summary>
public static class PermissionEvaluator
{
    /// <summary>Effective access for <paramref name="roleKeys"/> on <paramref name="entityKey"/>,
    /// unioning every matching role's grant (any role allowing an op → allowed). Within one role, a
    /// grant naming the entity beats the <c>*</c> wildcard. A field's rule = its per-role override
    /// (if any) else that role's entity default, OR-ed across roles.</summary>
    public static EntityAccess Evaluate(JsonNode? roles, IReadOnlyCollection<string> roleKeys, string entityKey)
    {
        if (roleKeys.Count == 0 || roles is not JsonArray roleArr) return EntityAccess.None;
        var wanted = new HashSet<string>(roleKeys);

        var grants = new List<Grant>();
        foreach (var role in roleArr.OfType<JsonObject>())
        {
            if (role["key"]?.GetValue<string>() is not { } k || !wanted.Contains(k)) continue;
            if (EffectiveGrant(role, entityKey) is { } g) grants.Add(g);
        }
        if (grants.Count == 0) return EntityAccess.None;

        bool create = grants.Any(g => g.Create);
        bool read = grants.Any(g => g.Read);
        bool update = grants.Any(g => g.Update);
        bool delete = grants.Any(g => g.Delete);

        var fields = new Dictionary<string, FieldRule>();
        foreach (var f in grants.SelectMany(g => g.Fields.Keys).Distinct())
        {
            // For each role: its explicit override for this field, else its entity-level default. OR across roles.
            bool fr = grants.Any(g => g.Fields.TryGetValue(f, out var o) ? o.Read ?? g.Read : g.Read);
            bool fu = grants.Any(g => g.Fields.TryGetValue(f, out var o) ? o.Update ?? g.Update : g.Update);
            fields[f] = new FieldRule(fr, fu);
        }

        // Commands (deny-by-default): the union across roles; '*' on any grant → all commands allowed.
        bool allCommands = grants.Any(g => g.Commands.Contains("*"));
        var commands = grants.SelectMany(g => g.Commands).Where(c => c != "*").ToHashSet();
        return new EntityAccess(create, read, update, delete, fields, commands, allCommands);
    }

    // The grant a single role applies to an entity: the entity-specific grant if present, else the
    // '*' wildcard, else none (this role grants nothing here).
    private static Grant? EffectiveGrant(JsonObject role, string entityKey)
    {
        var grantsArr = role["grants"] as JsonArray;
        if (grantsArr is null) return null;
        JsonObject? specific = null, wildcard = null;
        foreach (var g in grantsArr.OfType<JsonObject>())
        {
            var e = g["entity"]?.GetValue<string>();
            if (e == entityKey) specific = g;
            else if (e == "*") wildcard ??= g;
        }
        var chosen = specific ?? wildcard;
        return chosen is null ? null : Parse(chosen);
    }

    private static Grant Parse(JsonObject g)
    {
        var fields = new Dictionary<string, (bool? Read, bool? Update)>();
        foreach (var o in (g["fieldOverrides"] as JsonArray)?.OfType<JsonObject>() ?? Enumerable.Empty<JsonObject>())
            if (o["field"]?.GetValue<string>() is { } f)
                fields[f] = (Bool(o["read"]), Bool(o["update"]));
        var commands = (g["commands"] as JsonArray)?.OfType<JsonValue>()
            .Select(v => v.GetValue<string>()).ToHashSet() ?? new HashSet<string>();
        return new Grant(
            Bool(g["create"]) ?? false, Bool(g["read"]) ?? false,
            Bool(g["update"]) ?? false, Bool(g["delete"]) ?? false, fields, commands);
    }

    private static bool? Bool(JsonNode? n) =>
        n?.GetValueKind() is System.Text.Json.JsonValueKind.True ? true
        : n?.GetValueKind() is System.Text.Json.JsonValueKind.False ? false
        : (bool?)null;

    private sealed record Grant(bool Create, bool Read, bool Update, bool Delete,
        IReadOnlyDictionary<string, (bool? Read, bool? Update)> Fields, IReadOnlySet<string> Commands);
}

