using System.Text.Json.Nodes;

namespace AppBuilder.Runtime;

/// <summary>
/// What one caller's role may SEE of a record — the single derivation of that question, for every
/// path that hands data back.
///
/// <para><b>Why one place.</b> Ordinary CRUD stripped hidden fields; commands did not. A role with
/// <c>read:false</c> on <c>salary</c> could not list it, could not filter by it and could not
/// aggregate over it — and then ran any command it was granted and got the whole updated record
/// back, that field included. The projection was a habit at each call site rather than a rule, so a
/// second response path simply didn't inherit it.</para>
///
/// <para><b>Three channels, not one.</b> A record leaks the value directly; a command's
/// <c>successMessage</c> is a template resolved over the record, so <c>{{salary}}</c> leaks it in
/// prose; and an effect's <c>detail</c> string is rendered from the same record. Closing only the
/// first would have looked like a fix.</para>
///
/// <para>These are the CALLER-facing projections only. Effects still execute against the full
/// record, and the engine run log still stores the full detail — a webhook or a notification email
/// legitimately needs a hidden field, it just goes to a configured destination rather than back down
/// the wire to someone who may not read it.</para>
/// </summary>
public static class FieldProjection
{
    /// <summary>True when this role hides anything at all — the cheap check that lets every caller
    /// skip the work entirely for owners, admins and unrestricted roles.</summary>
    public static bool Restricts(EntityAccess access) => access.HiddenReadFields.Any();

    /// <summary>The record as this role may see it: a CLONE minus every hidden field. Cloned, not
    /// mutated — callers hold the live instance the data layer returned, and quietly emptying it
    /// would corrupt effect execution and the audit trail that run alongside.</summary>
    public static JsonObject? Project(EntityAccess access, JsonObject? record)
    {
        if (record is null) return null;
        var hidden = access.HiddenReadFields.ToHashSet(StringComparer.Ordinal);
        if (hidden.Count == 0) return record;
        var clone = (JsonObject)record.DeepClone();
        foreach (var f in hidden) clone.Remove(f);
        return clone;
    }

    /// <summary>Effect outcomes as this role may see them. <c>type</c>, <c>ok</c> and <c>skipped</c>
    /// stay — they say whether the action happened, which the caller is entitled to know. The
    /// <c>detail</c> string is dropped, because it is rendered from the record and there is no way to
    /// tell from here which parts of it came from a field they may not read.</summary>
    public static JsonArray? SanitizeEffects(EntityAccess access, JsonArray? effects)
    {
        if (effects is null || !Restricts(access)) return effects;
        var result = new JsonArray();
        foreach (var e in effects)
        {
            if (e is not JsonObject o) continue;
            var clean = new JsonObject { ["type"] = o["type"]?.DeepClone(), ["ok"] = o["ok"]?.DeepClone() };
            if (o["skipped"] is { } s) clean["skipped"] = s.DeepClone();
            result.Add(clean);
        }
        return result;
    }

    /// <summary>Warnings as this role may see them. Same reasoning as <see cref="SanitizeEffects"/>:
    /// a warning is <c>"{type}: {detail}"</c>, so the detail has to go, but the fact that an effect
    /// of that type failed must not — silently returning no warnings would tell the caller their
    /// action fully succeeded when it did not.</summary>
    public static IReadOnlyList<string>? SanitizeWarnings(EntityAccess access, IReadOnlyList<string>? warnings)
    {
        if (warnings is null || !Restricts(access)) return warnings;
        return warnings
            .Select(w => w.Split(':', 2) is [var type, _] ? $"{type}: (details hidden)" : "(details hidden)")
            .ToList();
    }
}

