    /// action fully succeeded when it did not.</summary>
    public static IReadOnlyList<string>? SanitizeWarnings(EntityAccess access, IReadOnlyList<string>? warnings)
    {
        if (warnings is null || !Restricts(access)) return warnings;
        return warnings
            .Select(w => w.Split(':', 2) is [var type, _] ? $"{type}: (details hidden)" : "(details hidden)")
            .ToList();
    }
}

