    {
        if (body.ValueKind != JsonValueKind.Object)
            throw new RecordException("request.body_invalid", "Expected a JSON object.");

        T record;
        try
        {
            record = body.Deserialize<T>(Json) ?? new T();
        }
        catch (JsonException ex)
        {
