24	/// public sealed class ExpenseController : RecordsController&lt;Expense&gt;
25	/// {
26	///     public ExpenseController(IRecordStore&lt;Expense&gt; store, AppPermissions permissions, ICurrentUser user)
27	///         : base(store, permissions, user) { }
28	/// }
29	/// </code>
30	///
