32	/// provider closing the generic over every discovered type, plus a route convention rewriting the
33	/// route from an attribute. It is clever, and for a library meeting its entities at runtime it is
34	/// the only option. We meet ours at build time, so we write the six lines. What that buys is a route
35	/// table you can read, a controller you can put a breakpoint in, and a place for the first
36	/// hand-written endpoint to go that does not require understanding the conjuring first.</para>
37	/// </summary>
38	public abstract class RecordsController<T> : ControllerBase where T : class, IRecord, new()
39	{
40	    private readonly IRecordStore<T> _store;
41	    private readonly AppPermissions _permissions;
42	
43	    protected RecordsController(IRecordStore<T> store, AppPermissions permissions, ICurrentUser user)
44	    {
45	        _store = store;
46	        _permissions = permissions;
47	        Caller = user;
48	    }
49	
50	    /// <summary>Who is asking. Named <c>Caller</c> rather than <c>User</c> because
51	    /// <see cref="ControllerBase.User"/> already means the raw <c>ClaimsPrincipal</c>, and two
52	    /// spellings of "the user" differing in what they let you check is exactly the pair somebody
53	    /// gets wrong at three in the morning.</summary>
54	    protected ICurrentUser Caller { get; }
55	
56	    private EntityAccess? _access;
57	
58	    /// <summary>Resolved once per request. Cheap — it reads compiled-in data and touches nothing
59	    /// else.</summary>
60	    protected EntityAccess Access => _access ??= ResolveAccess();
61	
62	    /// <summary>
63	    /// What this caller may do here. The definition's roles, for an application's own entities.
64	    ///
65	    /// <para>Overridable because not everything a generated application serves came from the
66	    /// definition — the built-in directory did not, and no role in the definition says anything
67	    /// about it. See <see cref="Organization.DirectoryController{T}"/>.</para>
68	    /// </summary>
69	    protected virtual EntityAccess ResolveAccess() =>
70	        PermissionResolver.Resolve(_permissions, Caller, _store.Descriptor.EntityKey);
71	
72	    protected RecordDescriptor<T> Descriptor => _store.Descriptor;
73	
74	    protected static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
75	
76	    /// <summary>
77	    /// A page of records.
78	    ///
79	    /// <para>Ordered by id and nothing else, on purpose: a page is only meaningful if the order it
80	    /// pages through is stable, and an unordered query gives the database licence to return rows in
81	    /// a different sequence each call. Sorting and filtering by the definition's own fields is
82	    /// generated per entity, where the field names and their types are known.</para>
83	    /// </summary>
84	    [HttpGet]
85	    public virtual async Task<IActionResult> List([FromQuery] int skip = 0, [FromQuery] int take = 50, CancellationToken ct = default)
86	    {
87	        if (!Access.Read) return Denied("read");
88	
89	        take = Math.Clamp(take, 1, MaxPageSize);
90	        skip = Math.Max(skip, 0);
91	
92	        var query = _store.Query();
93	        var total = await query.CountAsync(ct);
94	        var rows = await query.OrderBy(e => e.Id).Skip(skip).Take(take).ToListAsync(ct);
95	
96	        var items = new JsonArray();
97	        foreach (var row in rows) items.Add(RecordVisibility.Project(Access, row, Json));
98	
99	        return Ok(new JsonObject
100	        {
101	            ["items"] = items,
102	            ["total"] = total,
103	            ["skip"] = skip,
104	            ["take"] = take,
105	        });
106	    }
107	
108	    [HttpGet("{id}")]
109	    public virtual async Task<IActionResult> Get(string id, CancellationToken ct = default)
110	    {
111	        if (!Access.Read) return Denied("read");
