using System.Text.Json;
using System.Text.Json.Nodes;
using AppBuilder.Runtime;

namespace AppBuilder.Runtime.Tests;

/// <summary>
/// The platform's permission rules, checked against the same decision fixtures the standalone
/// generator's runtime is checked against.
///
/// <para><b>Why two implementations exist at all.</b> A generated standalone application resolves an
/// App Definition's <c>roles</c> with its own code, in the open-source repository, deliberately not
/// sharing this one. Sharing would create a coupling where a change made for standalone's reasons
/// alters what the platform enforces, and enforcement is the last place to accept a surprise.</para>
///
/// <para><b>Why that is safe.</b> Because duplication without a contract drifts, and drift in a
/// permission rule does not announce itself: it appears as somebody seeing a field they should not,
/// on one product only, months later. The contract is
/// <c>oss/cordango/tests/fixtures/permissions/*.json</c> — hand-written decisions, checked in as
/// data, asserted by both suites. Recording them from either implementation was the alternative, and
/// it would have made one side's bugs the definition of correct.</para>
///
/// <para>When a case here fails, ask which side moved: both suites failing means the fixture is
/// wrong, one failing means an implementation is.</para>
/// </summary>
public class PermissionFixtureTests
{
    public static TheoryData<string> Fixtures()
    {
        var data = new TheoryData<string>();
        foreach (var path in Directory.EnumerateFiles(FixtureDirectory, "*.json").OrderBy(p => p, StringComparer.Ordinal))
            data.Add(Path.GetFileName(path));
        return data;
    }

    [Theory]
    [MemberData(nameof(Fixtures))]
    public void Decisions_match_the_fixture(string fileName)
    {
        var fixture = JsonNode.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, fileName)))!.AsObject();
        var roles = fixture["roles"];
        var name = fixture["name"]?.GetValue<string>() ?? fileName;

        var cases = fixture["cases"]!.AsArray();
        Assert.NotEmpty(cases);

        for (var i = 0; i < cases.Count; i++)
        {
            var scenario = cases[i]!.AsObject();
            var roleKeys = scenario["roleKeys"]!.AsArray().Select(v => v!.GetValue<string>()).ToArray();
            var entity = scenario["entity"]!.GetValue<string>();
            var where = $"{fileName} case {i} ({name}), roles [{string.Join(", ", roleKeys)}] on '{entity}'";

            var access = PermissionEvaluator.Evaluate(roles, roleKeys, entity);

            var expect = scenario["expect"]!.AsObject();
            Assert.True(expect["create"]!.GetValue<bool>() == access.Create, $"{where}: create");
            Assert.True(expect["read"]!.GetValue<bool>() == access.Read, $"{where}: read");
            Assert.True(expect["update"]!.GetValue<bool>() == access.Update, $"{where}: update");
            Assert.True(expect["delete"]!.GetValue<bool>() == access.Delete, $"{where}: delete");

            foreach (var (field, rule) in Pairs(scenario["fields"]))
            {
                var expected = rule!.AsObject();
                Assert.True(expected["read"]!.GetValue<bool>() == access.CanReadField(field),
                    $"{where}: field '{field}' read");
                Assert.True(expected["update"]!.GetValue<bool>() == access.CanUpdateField(field),
                    $"{where}: field '{field}' update");
            }

            foreach (var (command, allowed) in Pairs(scenario["commands"]))
            {
                Assert.True(allowed!.GetValue<bool>() == access.CanRunCommand(command),
                    $"{where}: command '{command}'");
            }
        }
    }

    /// <summary>Guards the guard: an empty directory would leave every theory above unrun and the
    /// suite green, which is the one failure mode a data-driven test cannot report itself.</summary>
    [Fact]
    public void The_fixtures_are_actually_there()
    {
        var files = Directory.GetFiles(FixtureDirectory, "*.json");
        Assert.True(files.Length >= 6,
            $"Expected the shared permission fixtures in {FixtureDirectory}; found {files.Length}. "
            + "If oss/cordango is an uninitialised submodule, run git submodule update with the init flag.");
    }

    private static IEnumerable<(string Key, JsonNode? Value)> Pairs(JsonNode? node) =>
        node is JsonObject o ? o.Select(kv => (kv.Key, kv.Value)) : Enumerable.Empty<(string, JsonNode?)>();

    /// <summary>The fixtures live in the open-source repository because that is where the second
    /// implementation lives and where the contract is publishable. This side reaches into the
    /// submodule to read them.</summary>
    private static string FixtureDirectory =>
        Path.Combine(PlatformRoot(), "oss", "cordango", "tests", "fixtures", "permissions");

    private static string PlatformRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !Directory.Exists(Path.Combine(dir.FullName, "backend")))
            dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("platform repo root not found");
    }
}

