7	using System.Text.Json.Nodes;
8	using Cordango.Standalone.Security;
9	
10	namespace Cordango.Standalone.Tests;
11	
12	/// <summary>
13	/// The standalone permission rules, checked against the decision fixtures that Cordango Platform's
14	/// own suite also checks its implementation against.
15	///
16	/// <para>Two implementations of four rules, deliberately not sharing code, pinned to one set of
17	/// hand-written decisions. That is the whole arrangement: the platform never has to accept a change
18	/// made for standalone's reasons, and a divergence between them shows up as a red test in whichever
19	/// suite runs first rather than as a wrong answer in production.</para>
20	///
21	/// <para>If a case here fails, the interesting question is which side moved. Run the platform's
22	/// <c>PermissionFixtureTests</c> too: both failing means the fixture is wrong, one failing means an
23	/// implementation is.</para>
24	/// </summary>
25	public class PermissionFixtureTests
26	{
27	    public static TheoryData<string> Fixtures()
28	    {
29	        var data = new TheoryData<string>();
30	        foreach (var path in System.IO.Directory.EnumerateFiles(FixtureDirectory, "*.json").OrderBy(p => p, StringComparer.Ordinal))
31	            data.Add(Path.GetFileName(path));
32	        return data;
33	    }
34	
35	    [Theory]
36	    [MemberData(nameof(Fixtures))]
37	    public void Decisions_match_the_fixture(string fileName)
38	    {
39	        var fixture = JsonNode.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, fileName)))!.AsObject();
40	        var permissions = FixtureRoles.Read(fixture["roles"]);
41	        var name = fixture["name"]?.GetValue<string>() ?? fileName;
42	
43	        var cases = fixture["cases"]!.AsArray();
44	        Assert.NotEmpty(cases);
45	
46	        for (var i = 0; i < cases.Count; i++)
47	        {
48	            var scenario = cases[i]!.AsObject();
49	            var roleKeys = scenario["roleKeys"]!.AsArray().Select(v => v!.GetValue<string>()).ToArray();
50	            var entity = scenario["entity"]!.GetValue<string>();
51	            var where = $"{fileName} case {i} ({name}), roles [{string.Join(", ", roleKeys)}] on '{entity}'";
52	
53	            var access = PermissionResolver.Resolve(permissions, roleKeys, entity);
54	
55	            var expect = scenario["expect"]!.AsObject();
56	            Assert.Equal(expect["create"]!.GetValue<bool>(), access.Create);
57	            Assert.Equal(expect["read"]!.GetValue<bool>(), access.Read);
58	            Assert.Equal(expect["update"]!.GetValue<bool>(), access.Update);
59	            Assert.Equal(expect["delete"]!.GetValue<bool>(), access.Delete);
60	
61	            foreach (var (field, rule) in Pairs(scenario["fields"]))
62	            {
63	                var expected = rule!.AsObject();
64	                Assert.True(expected["read"]!.GetValue<bool>() == access.CanReadField(field),
65	                    $"{where}: field '{field}' read");
66	                Assert.True(expected["update"]!.GetValue<bool>() == access.CanUpdateField(field),
67	                    $"{where}: field '{field}' update");
68	            }
69	
70	            foreach (var (command, allowed) in Pairs(scenario["commands"]))
71	            {
72	                Assert.True(allowed!.GetValue<bool>() == access.CanRunCommand(command),
73	                    $"{where}: command '{command}'");
74	            }
75	        }
76	    }
77	
78	    /// <summary>
79	    /// Guards the guard. A directory that silently held no files, or a fixture that silently held no
80	    /// cases, would leave this class green while checking nothing — the failure mode every
81	    /// data-driven test has and the one nobody notices, because a passing suite looks the same
82	    /// either way.
83	    /// </summary>
84	    [Fact]
85	    public void The_fixtures_are_actually_there()
86	    {
87	        var files = System.IO.Directory.GetFiles(FixtureDirectory, "*.json");
88	        Assert.True(files.Length >= 6,
89	            $"Expected the permission decision fixtures in {FixtureDirectory}; found {files.Length} files. "
90	            + "They are the only thing keeping this implementation and the platform's from drifting apart.");
91	    }
92	
93	    private static IEnumerable<(string Key, JsonNode? Value)> Pairs(JsonNode? node) =>
94	        node is JsonObject o ? o.Select(kv => (kv.Key, kv.Value)) : [];
95	
96	    private static string FixtureDirectory =>
97	        Path.Combine(TestPaths.RepoRoot(), "tests", "fixtures", "permissions");
98	}
99	
100	/// <summary>
101	/// Turns a definition's <c>roles</c> array into the typed <see cref="AppPermissions"/> the runtime
102	/// uses.
103	///
104	/// <para>It lives in the test project rather than in the runtime, and that is the point: a generated
105	/// application has no JSON roles to read. The generator emits <c>AppPermissions</c> as C#, compiled
106	/// in, so the runtime never parses a definition at all. This class is that translation done at test
107	/// time, so the fixtures can be written in the definition's own vocabulary.</para>
108	/// </summary>
109	internal static class FixtureRoles
110	{
111	    public static AppPermissions Read(JsonNode? roles)
112	    {
113	        if (roles is not JsonArray array) return AppPermissions.None;
114	
115	        var definitions = new List<RoleDefinition>();
116	        foreach (var role in array.OfType<JsonObject>())
117	        {
118	            var key = role["key"]?.GetValue<string>();
119	            if (key is null) continue;
120	
121	            var grants = new List<EntityGrant>();
122	            foreach (var grant in (role["grants"] as JsonArray)?.OfType<JsonObject>() ?? [])
123	            {
124	                var entity = grant["entity"]?.GetValue<string>();
125	                if (entity is null) continue;
126	
127	                var overrides = new List<FieldOverride>();
128	                foreach (var o in (grant["fieldOverrides"] as JsonArray)?.OfType<JsonObject>() ?? [])
129	                    if (o["field"]?.GetValue<string>() is { } field)
130	                        overrides.Add(new FieldOverride(field, Bool(o["read"]), Bool(o["update"])));
131	
132	                var commands = (grant["commands"] as JsonArray)?
133	                    .Select(c => c!.GetValue<string>())
134	                    .ToArray() ?? [];
135	
136	                grants.Add(new EntityGrant(
137	                    entity,
138	                    Bool(grant["create"]) ?? false,
139	                    Bool(grant["read"]) ?? false,
140	                    Bool(grant["update"]) ?? false,
141	                    Bool(grant["delete"]) ?? false,
142	                    overrides,
143	                    commands));
144	            }
145	
146	            definitions.Add(new RoleDefinition(key, grants));
147	        }
148	
149	        return new AppPermissions(definitions);
150	    }
151	
152	    /// <summary>Absent and null both mean "said nothing", which for a field override is different
153	    /// from having said false.</summary>
154	    private static bool? Bool(JsonNode? node) => node?.GetValueKind() switch
155	    {
156	        JsonValueKind.True => true,
157	        JsonValueKind.False => false,
158	        _ => null,
159	    };
160	}

