        else if (underlying == typeof(long)) value = ParseOrThrow(raw, long.TryParse);
        else if (underlying == typeof(int)) value = ParseOrThrow(raw, int.TryParse);
        else if (underlying == typeof(decimal)) value = ParseOrThrow(raw, decimal.TryParse);
        else if (underlying == typeof(double)) value = ParseOrThrow(raw, double.TryParse);
        else if (underlying == typeof(DateOnly)) value = ParseOrThrow(raw, DateOnly.TryParse);
