24	/// <summary>
25	/// Turning a list request into a query the database runs.
26	///
27	/// <para><b>Why this is in the runtime and not generated.</b> Emitting a typed comparison per field
28	/// per operator would be sixteen field types times ten operators of near-identical code in every
29	/// application, and every one of them would have to be regenerated to fix a bug in any of them.
30	/// Building the expression once, from the property name the descriptor already carries, is the same
31	/// work done in one place — and it happens once per REQUEST, not once per row, so what runs against
32	/// the database is an ordinary parameterised query.</para>
33	///
34	/// <para><b>Fields are looked up, never interpolated.</b> A field key that is not in the descriptor
35	/// is refused by name rather than passed to anything. There is no path from a query string to a
36	/// column name here, which is what makes the difference between a filter and an injection.</para>
37	/// </summary>
38	public static class RecordQuery
39	{
40	    /// <summary>Everything a list request can ask for.</summary>
41	    public static IQueryable<T> Apply<T>(
42	        IQueryable<T> query,
43	        RecordDescriptor<T> descriptor,
44	        IReadOnlyList<RecordFilter> filters,
45	        IReadOnlyList<RecordSort> sort)
46	        where T : class, IRecord, new()
47	    {
48	        ArgumentNullException.ThrowIfNull(query);
49	        ArgumentNullException.ThrowIfNull(descriptor);
50	
51	        foreach (var filter in filters ?? []) query = Where(query, descriptor, filter);
52	        return OrderBy(query, descriptor, sort ?? []);
53	    }
54	
55	    private static IQueryable<T> Where<T>(IQueryable<T> query, RecordDescriptor<T> descriptor, RecordFilter filter)
56	        where T : class, IRecord, new()
57	    {
58	        var property = Property<T>(descriptor, filter.Field);
59	        var parameter = Expression.Parameter(typeof(T), "e");
60	        var member = Expression.Property(parameter, property);
61	
62	        var body = Compare(member, property.PropertyType, filter);
63	        return query.Where(Expression.Lambda<Func<T, bool>>(body, parameter));
64	    }
65	
66	    private static Expression Compare(MemberExpression member, Type type, RecordFilter filter)
67	    {
68	        // The absence tests come first: they are the two operators that do not need a value, and
69	        // treating a missing value as an error before checking for them would make them unusable.
70	        switch (filter.Operator)
71	        {
72	            case "isEmpty":
73	                return IsEmpty(member, type);
74	            case "isNotEmpty":
75	                return Expression.Not(IsEmpty(member, type));
76	        }
77	
78	        if (filter.Operator is "in" or "notIn")
79	        {
80	            var values = (filter.Value ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries)
81	                .Select(v => Constant(v, type))
82	                .ToList();
83	
84	            if (values.Count == 0)
85	            {
86	                // "in nothing" matches nothing, and "not in nothing" matches everything. Falling
87	                // through to an OR over an empty list would silently do the opposite of both.
88	                return Expression.Constant(filter.Operator == "notIn");
89	            }
90	
91	            Expression any = Expression.Equal(member, values[0]);
92	            for (var i = 1; i < values.Count; i++)
93	                any = Expression.OrElse(any, Expression.Equal(member, values[i]));
94	
95	            return filter.Operator == "in" ? any : Expression.Not(any);
96	        }
97	
98	        if (filter.Operator is "contains" or "startsWith")
99	        {
100	            if (type != typeof(string))
101	                throw new RecordException("query.operator_type",
102	                    $"'{filter.Operator}' compares text, and '{filter.Field}' is not text.");
103	
104	            var method = filter.Operator == "contains"
105	                ? typeof(string).GetMethod(nameof(string.Contains), [typeof(string)])!
106	                : typeof(string).GetMethod(nameof(string.StartsWith), [typeof(string)])!;
107	
108	            // A null column is not a match, and calling Contains on it would throw once the query
109	            // ran rather than when it was built.
