    /// command rather than once per row. Going through the serialiser also means a value arrives
    /// typed exactly as an ordinary PATCH of the same field would arrive — one conversion, not
    /// two.</para>
    /// </summary>
    private static string Read(T record, string field)
    {
        var node = JsonSerializer.SerializeToNode(record, Json)?.AsObject();
        return node?[field]?.ToString() ?? "";
    }

    private static void Write(T record, string field, string? value)
    {
        var node = JsonSerializer.SerializeToNode(record, Json)!.AsObject();
        node[field] = value is null ? null : System.Text.Json.Nodes.JsonValue.Create(value);

        var rewritten = node.Deserialize<T>(Json)!;

        // Copy the one field back rather than replacing the instance, so nothing else the caller
        // already set is lost.
        foreach (var descriptorField in Fields)
            if (descriptorField.Key == field)
                descriptorField.Copy(rewritten, record);
    }

    private IReadOnlyList<RecordField<T>> Fields => _store.Descriptor.Fields;

    private static string? Text(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.Null or JsonValueKind.Undefined => null,
        JsonValueKind.String => value.GetString(),
        _ => value.GetRawText(),
    };

    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
}

