old_end=s.index('    /// <summary>The field to add up, as a nullable decimal.')
new='''    /// <summary>The two values a grouped aggregate needs from each row, in a type EF can project
    /// into. An anonymous type would do, and cannot be named in the expression built below.</summary>
    private sealed class Pair<TKey>
    {
        public Pair(TKey? key, decimal? value) { Key = key; Value = value; }
        public TKey? Key { get; }
        public decimal? Value { get; }
    }

    /// <summary>
    /// Project each row to its group key and its number, then group.
    ///
    /// <para>Two steps rather than one because a lambda inside an expression tree has to be written
    /// out literally — <c>g.Sum(selector)</c> where <c>selector</c> is a variable does not compile,
    /// and cannot, since the compiler is building a tree rather than calling a method. Projecting
    /// first moves the splice to a place where the expression can be assembled by hand.</para>
    /// </summary>
    private static async Task<List<(TKey? Key, decimal? Value)>> Group<T, TKey>(
        IQueryable<T> query,
        Expression<Func<T, TKey?>> key,
        string operation,
        Expression<Func<T, decimal?>>? value,
        CancellationToken ct)
    {
        var parameter = Expression.Parameter(typeof(T), "e");
        var keyBody = Rewrite(key.Body, key.Parameters[0], parameter);
        var valueBody = value is null
            ? (Expression)Expression.Constant(null, typeof(decimal?))
            : Rewrite(value.Body, value.Parameters[0], parameter);

        var constructor = typeof(Pair<TKey>).GetConstructors()[0];
        var projection = Expression.Lambda<Func<T, Pair<TKey>>>(
            Expression.New(constructor, keyBody, valueBody), parameter);

        var groups = query.Select(projection).GroupBy(p => p.Key);

        var rows = operation switch
        {
            "count" => await groups.Select(g => new { g.Key, Value = (decimal?)g.Count() }).ToListAsync(ct),
            "sum" => await groups.Select(g => new { g.Key, Value = g.Sum(p => p.Value) }).ToListAsync(ct),
            "avg" => await groups.Select(g => new { g.Key, Value = g.Average(p => p.Value) }).ToListAsync(ct),
            "min" => await groups.Select(g => new { g.Key, Value = g.Min(p => p.Value) }).ToListAsync(ct),
            "max" => await groups.Select(g => new { g.Key, Value = g.Max(p => p.Value) }).ToListAsync(ct),
            _ => [],
        };

        return [.. rows.Select(r => (r.Key, r.Value))];
    }

    /// <summary>Re-point an expression at a different parameter, so two lambdas built separately can
    /// be combined into one projection.</summary>
    private static Expression Rewrite(Expression body, ParameterExpression from, ParameterExpression to) =>
        new ParameterSwap(from, to).Visit(body)!;

    private sealed class ParameterSwap(ParameterExpression from, ParameterExpression to) : ExpressionVisitor
    {
        protected override Expression VisitParameter(ParameterExpression node) =>
            node == from ? to : base.VisitParameter(node);
    }

