27	public static class RecordAggregate
28	{
29	    /// <summary>Grouping by the month a date falls in, rather than by the date itself — written as
30	    /// <c>month_of:spent_on</c> in a definition, because "spend per month" is the question and
31	    /// "spend per day, then added up by whoever is reading" is not.</summary>
32	    private const string MonthPrefix = "month_of:";
33	
34	    public static async Task<IReadOnlyList<AggregateBucket>> RunAsync<T>(
35	        IQueryable<T> query,
36	        RecordDescriptor<T> descriptor,
37	        string operation,
38	        string? field,
39	        string? groupBy,
40	        CancellationToken ct)
41	        where T : class, IRecord, new()
42	    {
43	        ArgumentNullException.ThrowIfNull(query);
44	        ArgumentNullException.ThrowIfNull(descriptor);
45	
46	        if (operation is not ("count" or "sum" or "avg" or "min" or "max"))
47	            throw new RecordException("aggregate.operation_unknown",
48	                $"'{operation}' is not an aggregate. Use count, sum, avg, min or max.");
49	
50	        if (operation != "count" && string.IsNullOrEmpty(field))
51	            throw new RecordException("aggregate.field_required", $"'{operation}' needs a field to work on.");
52	
53	        // Everything is projected to decimal? first, so one code path serves integers, decimals and
54	        // money instead of three near-identical ones differing only in the numeric type.
55	        var value = operation == "count" ? null : Numeric(descriptor, field!);
56	
57	        if (string.IsNullOrEmpty(groupBy))
58	        {
59	            var total = await Single(query, operation, value, ct);
60	            return [new AggregateBucket(null, total)];
61	        }
62	
63	        return await Grouped(query, descriptor, operation, value, groupBy, ct);
64	    }
65	
66	    private static async Task<decimal?> Single<T>(
67	        IQueryable<T> query, string operation, Expression<Func<T, decimal?>>? value, CancellationToken ct)
68	    {
69	        if (operation == "count") return await query.CountAsync(ct);
70	
71	        var numbers = query.Select(value!);
72	        return operation switch
73	        {
74	            "sum" => await numbers.SumAsync(ct),
75	            "avg" => await numbers.AverageAsync(ct),
76	            "min" => await numbers.MinAsync(ct),
77	            "max" => await numbers.MaxAsync(ct),
78	            _ => null,
79	        };
80	    }
81	
82	    private static async Task<IReadOnlyList<AggregateBucket>> Grouped<T>(
83	        IQueryable<T> query,
84	        RecordDescriptor<T> descriptor,
85	        string operation,
86	        Expression<Func<T, decimal?>>? value,
87	        string groupBy,
88	        CancellationToken ct)
89	        where T : class, IRecord, new()
90	    {
91	        if (groupBy.StartsWith(MonthPrefix, StringComparison.Ordinal))
92	        {
93	            var key = MonthKey(descriptor, groupBy[MonthPrefix.Length..]);
94	            var buckets = await Group(query, key, operation, value, ct);
95	
96	            // The database groups by a sortable number; the label is made here, where formatting is
97	            // cheap and does not have to be expressible in SQL.
98	            return [.. buckets
99	                .Where(b => b.Key is not null)
100	                .Select(b => new AggregateBucket(Month(b.Key!.Value), b.Value))
101	                .OrderBy(b => b.Key, StringComparer.Ordinal)];
102	        }
103	
104	        var text = TextKey(descriptor, groupBy);
105	        var grouped = await Group(query, text, operation, value, ct);
106	
107	        return [.. grouped
108	            .Select(b => new AggregateBucket(b.Key ?? "", b.Value))
109	            .OrderBy(b => b.Key, StringComparer.Ordinal)];
110	    }
111	
112	    /// <summary>The two values a grouped aggregate needs from each row, in a type EF can project
113	    /// into. An anonymous type would do, and cannot be named in the expression built below.</summary>
114	    private sealed class Pair<TKey>
115	    {
116	        public Pair(TKey? key, decimal? value) { Key = key; Value = value; }
117	        public TKey? Key { get; }
118	        public decimal? Value { get; }
119	    }
120	
121	    /// <summary>
122	    /// Project each row to its group key and its number, then group.
123	    ///
124	    /// <para>Two steps rather than one because a lambda inside an expression tree has to be written
125	    /// out literally — <c>g.Sum(selector)</c> where <c>selector</c> is a variable does not compile,
126	    /// and cannot, since the compiler is building a tree rather than calling a method. Projecting
127	    /// first moves the splice to a place where the expression can be assembled by hand.</para>
128	    /// </summary>
129	    private static async Task<List<(TKey? Key, decimal? Value)>> Group<T, TKey>(
