10	/// <summary>
11	/// The compiled manifest, read once into shapes the emitters can use.
12	///
13	/// <para><b>Read from the MANIFEST, never from the definition.</b> The two look alike and are not
14	/// the same document: the manifest is what the compiler produced — base fields prepended, defaults
15	/// filled, options coloured, processes canonicalised, commands synthesized from transitions, views
16	/// and pages invented where the author wrote none. An emitter reading the definition would generate
17	/// an application missing everything the compiler decided, and would do it silently, because the
18	/// definition is also a valid document.</para>
19	///
20	/// <para>This class does no inference of its own. Anything not in the manifest is absent here too;
21	/// where a default is needed the emitter says so at the point of use, so there is one place per
22	/// question rather than a second compiler hiding in the generator.</para>
23	/// </summary>
24	public sealed class AppModel
25	{
26	    private AppModel(JsonObject manifest, string definitionHash)
27	    {
28	        Manifest = manifest;
29	        DefinitionHash = definitionHash;
30	
31	        Key = Str(manifest["key"]) ?? "app";
32	        Name = Str(manifest["name"]) ?? Key;
33	        Version = Str(manifest["version"]) ?? "1.0.0";
34	        Description = Str(manifest["description"]);
35	        Namespace = Naming.Pascal(Key);
36	
37	        Entities = [.. Arr(manifest["entities"]).OfType<JsonObject>().Select(e => new EntityModel(e))];
38	        Views = [.. Arr(manifest["views"]).OfType<JsonObject>().Select(v => new ViewModel(v))];
39	        Pages = [.. Arr(manifest["pages"]).OfType<JsonObject>().Select(p => new PageModel(p))];
40	        Roles = [.. Arr(manifest["roles"]).OfType<JsonObject>()];
41	        Processes = [.. Arr(manifest["processes"]).OfType<JsonObject>().Select(p => new ProcessModel(p))];
42	        Commands = [.. Arr(manifest["commands"]).OfType<JsonObject>().Select(c => new CommandModel(c))];
43	        Workflows = [.. Arr(manifest["workflows"]).OfType<JsonObject>()];
44	        Theme = manifest["theme"] as JsonObject;
45	    }
46	
47	    public static AppModel From(CompiledAppArtifact artifact)
48	    {
49	        ArgumentNullException.ThrowIfNull(artifact);
50	        return new AppModel(artifact.Manifest, artifact.DefinitionHash);
51	    }
