98	{
99	    public EntityModel(JsonObject json)
100	    {
101	        Json = json;
102	        Key = AppModel.Str(json["key"]) ?? "entity";
103	        Label = AppModel.Str(json["label"]) ?? Key;
104	        LabelPlural = AppModel.Str(json["labelPlural"]) ?? Label + "s";
105	        Icon = AppModel.Str(json["icon"]);
106	        DisplayField = AppModel.Str(json["displayField"]);
107	        Kind = AppModel.Str(json["kind"]);
108	        // company_id and app_id never reach the standalone model. The compiler adds them because a
109	        // platform row has to say which tenant and which application it belongs to; here the answer
110	        // is the same in every row of every table forever, and a column that always holds one value
111	        // is a column somebody will eventually filter on and be confused by.
112	        Fields =
113	        [
114	            .. AppModel.Arr(json["fields"]).OfType<JsonObject>()
115	                .Select(f => new FieldModel(f, Key))
