35	    {
36	        ArgumentNullException.ThrowIfNull(app);
37	        var tables = SchemaModel.Build(app);
38	
39	        yield return Migration(app, tables);
40	        yield return Designer(app, tables);
41	        yield return Snapshot(app, tables);
