52	        source.Line();
53	        source.Line($"namespace {app.Namespace}.Migrations;");
54	        source.Line();
55	        source.Line($"/// <summary>Everything {app.Name} stores, created from nothing.</summary>");
56	        source.Open("public partial class InitialCreate : Migration");
57	
58	        source.Open("protected override void Up(MigrationBuilder migrationBuilder)");
