32	{
33	    /// <summary>
34	    /// Stock ASP.NET Core Identity with a cookie, and three deliberate adjustments.
35	    ///
36	    /// <para><b>Stock, on purpose.</b> This application does not share an authentication stack with
37	    /// anything — not with Cordango Platform, not with another generated application. Sign-in is the
38	    /// part of a system that is most damaging to get subtly wrong and least valuable to be clever
39	    /// about, so it is the framework's own implementation, which is reviewed by people whose whole
40	    /// job that is. Swapping it for single sign-on later means changing this file and nothing
41	    /// else.</para>
42	    /// </summary>
43	    public static IServiceCollection AddAppIdentity(this IServiceCollection services)
44	    {
45	        services
46	            .AddIdentity<AppUser, IdentityRole>(options =>
47	            {
48	                options.User.RequireUniqueEmail = true;
49	                options.Password.RequiredLength = 12;
50	                options.SignIn.RequireConfirmedAccount = false;
51	
52	                // Ten tries then a five-minute wait. Slow enough to make guessing pointless, short
53	                // enough that somebody who mistyped their own password is not locked out of their
54	                // afternoon.
55	                options.Lockout.MaxFailedAccessAttempts = 10;
56	                options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
57	            })
58	            .AddEntityFrameworkStores<AppIdentityDbContext>()
59	            .AddClaimsPrincipalFactory<AppClaimsFactory>()
60	            .AddDefaultTokenProviders();
61	
62	        services.ConfigureApplicationCookie(options =>
63	        {
64	            options.Cookie.Name = "{{AppKey}}-session";
65	            options.Cookie.HttpOnly = true;
66	            options.Cookie.SameSite = SameSiteMode.Lax;
67	            options.Cookie.SecurePolicy = CookieSecurePolicy.SameAsRequest;
68	            options.ExpireTimeSpan = TimeSpan.FromDays(14);
69	            options.SlidingExpiration = true;
70	
71	            // Adjustment two: this is an API, so an unauthenticated call gets a status code rather
72	            // than a redirect to a login page that does not exist on the server. A 302 to
73	            // /Account/Login reaches a fetch() as an opaque success, and the client renders an empty
74	            // list instead of a sign-in prompt.
75	            options.Events.OnRedirectToLogin = context =>
76	            {
77	                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
78	                return Task.CompletedTask;
79	            };
