    private static string GeneratePassword()
    {
        const string lower = "abcdefghijkmnopqrstuvwxyz";
        const string upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
        const string digits = "23456789";
        const string symbols = "!@#$%^&*-_=+";

        // No I/l/1/O/0. Somebody is going to read this out of a terminal and type it into a browser.
        var all = lower + upper + digits + symbols;

        var characters = new List<char>
        {
            Pick(lower), Pick(upper), Pick(digits), Pick(symbols),
        };

        while (characters.Count < 20) characters.Add(Pick(all));

        // Shuffled, so the four required classes are not always in the first four positions.
        for (var i = characters.Count - 1; i > 0; i--)
        {
            var j = RandomNumberGenerator.GetInt32(i + 1);
            (characters[i], characters[j]) = (characters[j], characters[i]);
        }

        return new string([.. characters]);

        static char Pick(string pool) => pool[RandomNumberGenerator.GetInt32(pool.Length)];
    }''')

